from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['control_units', 'sensor_kits', 'cooling_racks', 'power_modules']
    num_products = len(products)

    # Parameters
    unit_profit = [27, 24, 36, 19]
    setup_cost = [97, 53, 110, 83]
    labor_time = [6, 6, 4, 5]
    max_quantity = [15, 17, 9, 16]
    total_labor = 163

    # Decision variables
    x = [solver.IntVar(0, max_quantity[i], f'x_{i}') for i in range(num_products)]
    y = [solver.BoolVar(f'y_{i}') for i in range(num_products)]

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(num_products):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -setup_cost[i])
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    labor_constraint = solver.Constraint(0, total_labor)
    for i in range(num_products):
        labor_constraint.SetCoefficient(x[i], labor_time[i])

    # Setup activation constraints
    for i in range(num_products):
        setup_constraint = solver.Constraint(-solver.infinity(), 0)
        setup_constraint.SetCoefficient(x[i], 1)
        setup_constraint.SetCoefficient(y[i], -max_quantity[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value(),
        "production_quantities": [x[i].solution_value() for i in range(num_products)],
        "setup_indicators": [y[i].solution_value() for i in range(num_products)]
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
