from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 15, 'x1')  # cooling_racks quantity
    x2 = solver.IntVar(0, 11, 'x2')  # control_units quantity
    x3 = solver.IntVar(0, 11, 'x3')  # power_modules quantity

    y1 = solver.BoolVar('y1')  # cooling_racks activation
    y2 = solver.BoolVar('y2')  # control_units activation
    y3 = solver.BoolVar('y3')  # power_modules activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 34)
    objective.SetCoefficient(y1, -58)
    objective.SetCoefficient(x2, 34)
    objective.SetCoefficient(y2, -72)
    objective.SetCoefficient(x3, 30)
    objective.SetCoefficient(y3, -48)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(5 * x1 + 6 * x2 + 6 * x3 <= 99)

    # Production capacity constraints
    solver.Add(x1 <= 15)
    solver.Add(x2 <= 11)
    solver.Add(x3 <= 11)

    # Linking constraints
    solver.Add(x1 <= 15 * y1)
    solver.Add(x2 <= 11 * y2)
    solver.Add(x3 <= 11 * y3)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x1": x1.solution_value(),
            "x2": x2.solution_value(),
            "x3": x3.solution_value(),
            "y1": y1.solution_value(),
            "y2": y2.solution_value(),
            "y3": y3.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

