from ortools.linear_solver import pywraplp
import json

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define decision variables
    flex_circuit = solver.NumVar(0, solver.infinity(), 'flex_circuit')
    eco_fuel = solver.NumVar(0, solver.infinity(), 'eco_fuel')
    prime_steel = solver.NumVar(0, solver.infinity(), 'prime_steel')
    aero_foam = solver.NumVar(0, solver.infinity(), 'aero_foam')

    # Define objective function
    objective = solver.Objective()
    objective.SetCoefficient(flex_circuit, 30)
    objective.SetCoefficient(eco_fuel, 43)
    objective.SetCoefficient(prime_steel, 21)
    objective.SetCoefficient(aero_foam, 43)
    objective.SetMaximization()

    # Add constraints
    # Machine hours constraint
    solver.Add(1 * flex_circuit + 4 * eco_fuel + 4 * prime_steel + 1 * aero_foam <= 60)

    # Raw material constraint
    solver.Add(2 * flex_circuit + 2 * eco_fuel + 1 * prime_steel + 3 * aero_foam <= 38)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"FlexCircuit: {flex_circuit.solution_value()}")
        print(f"EcoFuel: {eco_fuel.solution_value()}")
        print(f"PrimeSteel: {prime_steel.solution_value()}")
        print(f"AeroFoam: {aero_foam.solution_value()}")
        print(f"Total profit: {objective.Value()}")
    else:
        print("No optimal solution found")

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

