from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'x1')  # AeroFoam
    x2 = solver.IntVar(0, solver.infinity(), 'x2')  # SmartGlass
    x3 = solver.IntVar(0, solver.infinity(), 'x3')  # PrimeSteel

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 32)
    objective.SetCoefficient(x2, 20)
    objective.SetCoefficient(x3, 18)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint: 3x1 + x2 + 6x3 <= 47
    solver.Add(3 * x1 + x2 + 6 * x3 <= 47)

    # Raw material constraint: 2x1 + 5x2 + 5x3 <= 73
    solver.Add(2 * x1 + 5 * x2 + 5 * x3 <= 73)

    # Skilled labor constraint: 2x1 + 4x2 + 6x3 <= 58
    solver.Add(2 * x1 + 4 * x2 + 6 * x3 <= 58)

    # Solve the problem
    status = solver.Solve()

    # Check if solution is optimal
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"AeroFoam (x1): {x1.solution_value()}")
        print(f"SmartGlass (x2): {x2.solution_value()}")
        print(f"PrimeSteel (x3): {x3.solution_value()}")
        print(f"Total profit: {objective.Value()}")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("No optimal solution found")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

