def solve_knapsack():
    # 创建求解器
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # 设备数据
    items = ['sensor pod', 'portable scanner', 'edge server', 'relay box', 'backup battery', 'thermal camera']
    values = [38, 26, 44, 30, 44, 34]
    weights = [7, 8, 10, 5, 2, 8]
    capacity = 21

    # 创建决策变量
    x = []
    for i in range(len(items)):
        x.append(solver.BoolVar(f'x_{i}'))

    # 设置目标函数：最大化总价值
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

