def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 20, 'x1')  # Power modules quantity
    x2 = solver.IntVar(0, 9, 'x2')   # Battery packs quantity
    x3 = solver.IntVar(0, 19, 'x3')  # Control units quantity

    y1 = solver.BoolVar('y1')  # Power modules activation
    y2 = solver.BoolVar('y2')  # Battery packs activation
    y3 = solver.BoolVar('y3')  # Control units activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 23)
    objective.SetCoefficient(x2, 18)
    objective.SetCoefficient(x3, 22)
    objective.SetCoefficient(y1, -84)
    objective.SetCoefficient(y2, -78)
    objective.SetCoefficient(y3, -100)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(3 * x1 + 4 * x2 + 2 * x3 <= 74)

    # Activation constraints
    solver.Add(x1 <= 20 * y1)
    solver.Add(x2 <= 9 * y2)
    solver.Add(x3 <= 19 * y3)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

