def solve_knapsack():
    # Step 1: Problem Description
    # 0-1 knapsack problem with 6 items, capacity 17

    # Step 2: Sets and Parameters
    items = ['scanner', 'router', 'relay', 'sensor', 'server', 'battery']
    values = [45, 20, 27, 32, 32, 26]
    weights = [6, 6, 2, 6, 4, 6]
    capacity = 17

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i in range(len(items)):
        x[i] = solver.BoolVar(f'x_{i}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Step 5: Constraints
    weight_constraint = solver.Constraint(0, capacity)
    for i in range(len(items)):
        weight_constraint.SetCoefficient(x[i], weights[i])

    # Step 6: Mathematical Model Summary
    # Maximize: 45*x0 + 20*x1 + 27*x2 + 32*x3 + 32*x4 + 26*x5
    # Subject to: 6*x0 + 6*x1 + 2*x2 + 6*x3 + 4*x4 + 6*x5 ≤ 17
    # x_i ∈ {0,1} for all i

    # Step 7: Nonlinear Relationships
    # None - this is a linear MILP

    # Step 8: Final Model and Implementation Considerations
    # Solve using OR-Tools linear solver
    status = solver.Solve()

    # Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    for i in range(len(items)):
        if x[i].solution_value() > 0.5:
            selected_items.append(items[i])
            total_value += values[i]
            total_weight += weights[i]

    # Print result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

