from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    eco_fuel = solver.NumVar(0, solver.infinity(), 'eco_fuel')
    flex_circuit = solver.NumVar(0, solver.infinity(), 'flex_circuit')
    bio_resin = solver.NumVar(0, solver.infinity(), 'bio_resin')
    prime_steel = solver.NumVar(0, solver.infinity(), 'prime_steel')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(eco_fuel, 42)
    objective.SetCoefficient(flex_circuit, 19)
    objective.SetCoefficient(bio_resin, 24)
    objective.SetCoefficient(prime_steel, 42)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(5 * eco_fuel + 2 * flex_circuit + 4 * bio_resin + 2 * prime_steel <= 59)

    # Raw material constraint
    solver.Add(2 * eco_fuel + 1 * flex_circuit + 3 * bio_resin + 4 * prime_steel <= 45)

    # Solve the problem
    status = solver.Solve()

    # Check if optimal solution found
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = solver.Objective().Value()
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

