from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Data
    products = ['sensor_kits', 'control_units', 'battery_packs']
    unit_profit = [36, 31, 26]
    fixed_cost = [67, 65, 84]
    labor_time = [3, 3, 4]
    max_production = [11, 9, 12]
    total_labor_limit = 64

    # Decision variables
    x = []
    y = []
    for i in range(len(products)):
        # Production quantity variables
        x_i = solver.IntVar(0, max_production[i], f'x_{i}')
        x.append(x_i)
        # Activation variables
        y_i = solver.BoolVar(f'y_{i}')
        y.append(y_i)

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(len(products)):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -fixed_cost[i])
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    labor_constraint = solver.Constraint(0, total_labor_limit)
    for i in range(len(products)):
        labor_constraint.SetCoefficient(x[i], labor_time[i])

    # Activation constraints
    for i in range(len(products)):
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(x[i], 1)
        activation_constraint.SetCoefficient(y[i], -max_production[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value(),
        "production": [x[i].solution_value() for i in range(len(products))],
        "activation": [y[i].solution_value() for i in range(len(products))]
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

