import json

def main():
    # Step 1: Problem Description
    # Assign 4 tasks to 4 members with minimal total cost

    # Step 2: Sets and Parameters
    members = ['Emery', 'Bailey', 'Alex', 'Drew']
    tasks = ['inventory sync', 'order batching', 'line inspection', 'routing audit']

    # Cost matrix: c[m][t] = cost of member m doing task t
    costs = {
        'Emery': [27, 9, 24, 26],
        'Bailey': [24, 13, 15, 15],
        'Alex': [24, 16, 14, 8],
        'Drew': [18, 26, 8, 21]
    }

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i, member in enumerate(members):
        for j, task in enumerate(tasks):
            x[(member, task)] = solver.IntVar(0, 1, f'x_{member}_{task}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for member in members:
        for j, task in enumerate(tasks):
            objective.SetCoefficient(x[(member, task)], costs[member][j])
    objective.SetMinimization()

    # Step 5: Constraints
    # Each task assigned to exactly one member
    for j, task in enumerate(tasks):
        constraint = solver.Constraint(1, 1)
        for member in members:
            constraint.SetCoefficient(x[(member, task)], 1)

    # Each member assigned exactly one task
    for member in members:
        constraint = solver.Constraint(1, 1)
        for j, task in enumerate(tasks):
            constraint.SetCoefficient(x[(member, task)], 1)

    # Step 6: Solve the problem
    status = solver.Solve()

    # Step 7: Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for member in members:
            for j, task in enumerate(tasks):
                if x[(member, task)].solution_value() > 0.5:
                    assignment[member] = task
                    break
    else:
        total_cost = None
        assignment = None

    # Step 8: Output results
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

