import json

def solve_production_optimization():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define decision variables
    bio_resin = solver.IntVar(0, solver.infinity(), 'BioResin')
    smart_glass = solver.IntVar(0, solver.infinity(), 'SmartGlass')
    prime_steel = solver.IntVar(0, solver.infinity(), 'PrimeSteel')
    flex_circuit = solver.IntVar(0, solver.infinity(), 'FlexCircuit')
    eco_fuel = solver.IntVar(0, solver.infinity(), 'EcoFuel')

    # Define objective function
    objective = solver.Objective()
    objective.SetCoefficient(bio_resin, 37)
    objective.SetCoefficient(smart_glass, 46)
    objective.SetCoefficient(prime_steel, 48)
    objective.SetCoefficient(flex_circuit, 48)
    objective.SetCoefficient(eco_fuel, 35)
    objective.SetMaximization()

    # Add constraints
    # Machine hours constraint
    solver.Add(1 * bio_resin + 4 * smart_glass + 1 * prime_steel + 6 * flex_circuit + 2 * eco_fuel <= 81)

    # Raw material constraint
    solver.Add(6 * bio_resin + 4 * smart_glass + 1 * prime_steel + 6 * flex_circuit + 2 * eco_fuel <= 102)

    # Skilled labor constraint
    solver.Add(6 * bio_resin + 5 * smart_glass + 4 * prime_steel + 2 * flex_circuit + 1 * eco_fuel <= 86)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

