import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'FlexCircuit')
    x2 = solver.IntVar(0, solver.infinity(), 'AeroFoam')
    x3 = solver.IntVar(0, solver.infinity(), 'PrimeSteel')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 32)
    objective.SetCoefficient(x2, 32)
    objective.SetCoefficient(x3, 25)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(2 * x1 + 4 * x2 + 3 * x3 <= 49)

    # Raw material constraint
    solver.Add(3 * x1 + 3 * x2 + 2 * x3 <= 51)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        flex_circuit = x1.solution_value()
        aero_foam = x2.solution_value()
        prime_steel = x3.solution_value()
        total_profit = objective.Value()

        print(f"Optimal production plan:")
        print(f"FlexCircuit: {flex_circuit} units")
        print(f"AeroFoam: {aero_foam} units")
        print(f"PrimeSteel: {prime_steel} units")
        print(f"Total profit: {total_profit}")

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

