from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products and their parameters
    products = {
        'power_modules': {'profit': 27, 'setup_cost': 50, 'time': 5, 'max_qty': 8},
        'sensor_kits': {'profit': 33, 'setup_cost': 51, 'time': 3, 'max_qty': 18},
        'battery_packs': {'profit': 22, 'setup_cost': 55, 'time': 5, 'max_qty': 10},
        'control_units': {'profit': 31, 'setup_cost': 62, 'time': 6, 'max_qty': 14}
    }

    # Decision variables
    x = {}  # Binary activation variables
    q = {}  # Integer production quantity variables

    for p, params in products.items():
        x[p] = solver.BoolVar(f'x_{p}')
        q[p] = solver.IntVar(0, params['max_qty'], f'q_{p}')

    # Objective function: maximize net profit
    objective = solver.Objective()
    for p, params in products.items():
        objective.SetCoefficient(q[p], params['profit'])
        objective.SetCoefficient(x[p], -params['setup_cost'])
    objective.SetMaximization()

    # Constraints
    # 1. Labor time constraint
    labor_constraint = solver.Constraint(0, 128)
    for p, params in products.items():
        labor_constraint.SetCoefficient(q[p], params['time'])

    # 2. Activation constraints: if q_p > 0 then x_p must be 1
    for p, params in products.items():
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(q[p], 1)
        activation_constraint.SetCoefficient(x[p], -params['max_qty'])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': objective.Value(),
        'production_plan': {p: q[p].solution_value() for p in products},
        'activation': {p: x[p].solution_value() for p in products}
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

