from ortools.linear_solver import pywraplp
import json

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define decision variables
    eco_fuel = solver.IntVar(0, solver.infinity(), 'eco_fuel')
    aero_foam = solver.IntVar(0, solver.infinity(), 'aero_foam')
    prime_steel = solver.IntVar(0, solver.infinity(), 'prime_steel')
    smart_glass = solver.IntVar(0, solver.infinity(), 'smart_glass')

    # Define objective function
    objective = solver.Objective()
    objective.SetCoefficient(eco_fuel, 37)
    objective.SetCoefficient(aero_foam, 43)
    objective.SetCoefficient(prime_steel, 28)
    objective.SetCoefficient(smart_glass, 30)
    objective.SetMaximization()

    # Add constraints
    # Machine hours constraint
    solver.Add(5 * eco_fuel + 1 * aero_foam + 6 * prime_steel + 4 * smart_glass <= 88)

    # Raw material constraint
    solver.Add(2 * eco_fuel + 1 * aero_foam + 1 * prime_steel + 3 * smart_glass <= 32)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        eco_fuel_val = eco_fuel.solution_value()
