def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_aero = solver.IntVar(0, solver.infinity(), 'x_aero')
    x_bio = solver.IntVar(0, solver.infinity(), 'x_bio')
    x_prime = solver.IntVar(0, solver.infinity(), 'x_prime')
    x_eco = solver.IntVar(0, solver.infinity(), 'x_eco')
    x_flex = solver.IntVar(0, solver.infinity(), 'x_flex')

    # Objective function: maximize total profit
    solver.Maximize(45 * x_aero + 21 * x_bio + 20 * x_prime + 45 * x_eco + 23 * x_flex)

    # Constraints
    # Machine hours constraint
    solver.Add(6 * x_aero + 1 * x_bio + 6 * x_prime + 1 * x_eco + 4 * x_flex <= 83)

    # Raw material constraint
    solver.Add(5 * x_aero + 3 * x_bio + 3 * x_prime + 3 * x_eco + 3 * x_flex <= 87)

    # Skilled labor constraint
    solver.Add(5 * x_aero + 6 * x_bio + 6 * x_prime + 3 * x_eco + 6 * x_flex <= 119)

    # Solve the problem
    status = solver.Solve()

    # Print the results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found with objective value: {solver.Objective().Value()}")
        print(f"AeroFoam: {x_aero.solution_value()}")
