def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_CU = solver.IntVar(0, 14, 'x_CU')  # Control units production quantity
    x_SK = solver.IntVar(0, 17, 'x_SK')  # Sensor kits production quantity
    x_BP = solver.IntVar(0, 20, 'x_BP')  # Battery packs production quantity

    y_CU = solver.BoolVar('y_CU')  # Control units activation
    y_SK = solver.BoolVar('y_SK')  # Sensor kits activation
    y_BP = solver.BoolVar('y_BP')  # Battery packs activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_CU, 28)
    objective.SetCoefficient(x_SK, 36)
    objective.SetCoefficient(x_BP, 34)
