def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_B = solver.IntVar(0, 8, 'x_B')  # Battery packs quantity
    x_C = solver.IntVar(0, 9, 'x_C')  # Control units quantity
    x_P = solver.IntVar(0, 9, 'x_P')  # Power modules quantity

    y_B = solver.BoolVar('y_B')  # Battery packs activation
    y_C = solver.BoolVar('y_C')  # Control units activation
    y_P = solver.BoolVar('y_P')  # Power modules activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_B, 33)
    objective.SetCoefficient(x_C, 36)
    objective.SetCoefficient(x_P, 23)
    objective.SetCoefficient(y_B, -99)
    objective.SetCoefficient(y_C, -67)
    objective.SetCoefficient(y_P, -106)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(5 * x_B + 5 * x_C + 4 * x_P <= 62)

    # Production limits (already handled by variable bounds)

    # Activation constraints
    solver.Add(x_B <= 8 * y_B)
    solver.Add(x_C <= 9 * y_C)
    solver.Add(x_P <= 9 * y_P)

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value(),
        'production': {
            'battery_packs': x_B.solution_value(),
            'control_units': x_C.solution_value(),
            'power_modules': x_P.solution_value()
        },
        'activation': {
            'battery_packs': y_B.solution_value(),
            'control_units': y_C.solution_value(),
            'power_modules': y_P.solution_value()
        }
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

