from ortools.linear_solver import pywraplp

def solve_production_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    flex_circuit = solver.NumVar(0, solver.infinity(), 'flex_circuit')
    bio_resin = solver.NumVar(0, solver.infinity(), 'bio_resin')
    eco_fuel = solver.NumVar(0, solver.infinity(), 'eco_fuel')
    prime_steel = solver.NumVar(0, solver.infinity(), 'prime_steel')
    aero_foam = solver.NumVar(0, solver.infinity(), 'aero_foam')

    # Objective function: maximize total profit
    solver.Maximize(18 * flex_circuit + 26 * bio_resin + 46 * eco_fuel + 
                   31 * prime_steel + 42 * aero_foam)

    # Constraints
    # Machine hours constraint
    solver.Add(6 * flex_circuit + 3 * bio_resin + 2 * eco_fuel + 
               2 * prime_steel + 5 * aero_foam <= 96)

    # Raw material constraint
    solver.Add(1 * flex_circuit + 2 * bio_resin + 3 * eco_fuel + 
               5 * prime_steel + 1 * aero_foam <= 55)

    # Skilled labor constraint
    solver.Add(5 * flex_circuit + 3 * bio_resin + 3 * eco_fuel + 
               6 * prime_steel + 3 * aero_foam <= 111)

    # Solve the problem
    status = solver.Solve()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": solver.Objective().Value()
    }

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_production_allocation()

