import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_c = solver.IntVar(0, 12, 'x_cooling')  # cooling racks production
    x_co = solver.IntVar(0, 20, 'x_control')  # control units production
    x_s = solver.IntVar(0, 12, 'x_sensor')  # sensor kits production

    y_c = solver.BoolVar('y_cooling')  # cooling racks activation
    y_co = solver.BoolVar('y_control')  # control units activation
    y_s = solver.BoolVar('y_sensor')  # sensor kits activation

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x_c, 36)
    objective.SetCoefficient(x_co, 18)
    objective.SetCoefficient(x_s, 34)
    objective.SetCoefficient(y_c, -84)
    objective.SetCoefficient(y_co, -57)
    objective.SetCoefficient(y_s, -100)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(2 * x_c + 3 * x_co + 3 * x_s <= 54)

    # Activation constraints
    solver.Add(x_c <= 12 * y_c)
    solver.Add(x_co <= 20 * y_co)
    solver.Add(x_s <= 12 * y_s)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"Cooling racks: {x_c.solution_value()}, Activation: {y_c.solution_value()}")
        print(f"Control units: {x_co.solution_value()}, Activation: {y_co.solution_value()}")
        print(f"Sensor kits: {x_s.solution_value()}, Activation: {y_s.solution_value()}")
        print(f"Net profit: {objective.Value()}")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

