import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define items with their values and weights
    items = [
        ('thermal camera', 36, 2),
        ('field router', 33, 2),
        ('edge server', 27, 8),
        ('relay box', 43, 4),
        ('sensor pod', 12, 2),
        ('backup battery', 33, 3)
    ]

    # Decision variables
    x = []
    for name, value, weight in items:
        x.append(solver.BoolVar(name))

    # Objective function: maximize total value
    objective = solver.Objective()
    for i, (name, value, weight) in enumerate(items):
        objective.SetCoefficient(x[i], value)
    objective.SetMaximization()

    # Weight constraint
    weight_constraint = solver.Constraint(0, 9)
    for i, (name, value, weight) in enumerate(items):
        weight_constraint.SetCoefficient(x[i], weight)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    for i, (name, value, weight) in enumerate(items):
        if x[i].solution_value() > 0.5:
            selected_items.append(name)
            total_value += value
            total_weight += weight

    # Print results
    print(f"Status: {status}")
    print(f"Selected items: {selected_items}")
    print(f"Total value: {total_value}")
    print(f"Total weight: {total_weight}")

    # Return result in required format
    return {
        "status": "OPTIMAL" if status == solver.OPTIMAL else "OTHER",
        "objective_value": total_value
    }

