def main():
    # Step 1: Problem Description
    # Assign 4 tasks to 4 members with minimum total cost

    # Step 2: Sets and Parameters
    members = ['Drew', 'Finley', 'Casey', 'Emery']
    tasks = ['routing audit', 'inventory sync', 'line inspection', 'order batching']

    # Cost matrix: c[m][t] = cost of member m doing task t
    costs = [
        [15, 17, 13, 8],   # Drew
        [23, 22, 26, 16],  # Finley
        [11, 20, 19, 18],  # Casey
        [23, 12, 24, 19]   # Emery
    ]

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], costs[i][j])
    objective.SetMinimization()

    # Step 5: Constraints
    # Each task must be assigned to exactly one member
    for j in range(len(tasks)):
        constraint = solver.Constraint(1, 1)
        for i in range(len(members)):
            constraint.SetCoefficient(x[i, j], 1)

    # Each member must be assigned exactly one task
    for i in range(len(members)):
        constraint = solver.Constraint(1, 1)
        for j in range(len(tasks)):
            constraint.SetCoefficient(x[i, j], 1)

    # Step 6-7: Model Summary and Nonlinear Relationships
    # This is a linear assignment problem with no nonlinear relationships

    # Step 8: Solve and Implementation
    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        print("Optimal assignment found:")
        total_cost = 0
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    print(f"{members[i]} assigned to {tasks[j]} with cost {costs[i][j]}")
                    total_cost += costs[i][j]
        print(f"Total cost: {total_cost}")
    else:
        print("No optimal solution found")

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

