from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products and their parameters
    products = ['sensor_kits', 'control_units', 'battery_packs', 'cooling_racks']
    unit_profit = {'sensor_kits': 36, 'control_units': 27, 'battery_packs': 25, 'cooling_racks': 18}
    fixed_cost = {'sensor_kits': 76, 'control_units': 51, 'battery_packs': 78, 'cooling_racks': 84}
    unit_time = {'sensor_kits': 4, 'control_units': 5, 'battery_packs': 3, 'cooling_racks': 2}
    max_production = {'sensor_kits': 9, 'control_units': 20, 'battery_packs': 15, 'cooling_racks': 11}
    total_time = 138

    # Decision variables
    x = {}  # Binary activation variables
    y = {}  # Integer production quantity variables

    for p in products:
        x[p] = solver.BoolVar(f'produce_{p}')
        y[p] = solver.IntVar(0, max_production[p], f'quantity_{p}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for p in products:
        objective.SetCoefficient(y[p], unit_profit[p])
        objective.SetCoefficient(x[p], -fixed_cost[p])
    objective.SetMaximization()

    # Constraints
    # 1. Labor time constraint
    solver.Add(sum(unit_time[p] * y[p] for p in products) <= total_time)

    # 2. Activation constraints: if y_p > 0, then x_p must be 1
    for p in products:
        solver.Add(y[p] <= max_production[p] * x[p])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            'status': 'OPTIMAL',
            'objective_value': objective.Value(),
            'production_plan': {p: int(y[p].solution_value()) for p in products},
            'activation': {p: int(x[p].solution_value()) for p in products}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': None,
            'production_plan': None,
            'activation': None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

