def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_cr = solver.IntVar(0, 14, 'x_cr')  # cooling racks quantity
    x_sk = solver.IntVar(0, 14, 'x_sk')  # sensor kits quantity
    x_bp = solver.IntVar(0, 10, 'x_bp')  # battery packs quantity

    y_cr = solver.BoolVar('y_cr')  # cooling racks activation
    y_sk = solver.BoolVar('y_sk')  # sensor kits activation
    y_bp = solver.BoolVar('y_bp')  # battery packs activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_cr, 36)
    objective.SetCoefficient(x_sk, 35)
    objective.SetCoefficient(x_bp, 33)
    objective.SetCoefficient(y_cr, -74)
    objective.SetCoefficient(y_sk, -76)
    objective.SetCoefficient(y_bp, -69)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(2 * x_cr + 3 * x_sk + 3 * x_bp <= 60)

    # Production capacity constraints
    solver.Add(x_cr <= 14)
    solver.Add(x_sk <= 14)
    solver.Add(x_bp <= 10)

    # Activation constraints
    solver.Add(x_cr <= 14 * y_cr)
    solver.Add(x_sk <= 14 * y_sk)
    solver.Add(x_bp <= 10 * y_bp)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": solver.Objective().Value(),
            "x_cr": x_cr.solution_value(),
            "x_sk": x_sk.solution_value(),
            "x_bp": x_bp.solution_value(),
            "y_cr": y_cr.solution_value(),
            "y_sk": y_sk.solution_value(),
            "y_bp": y_bp.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0.0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

