import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Binary activation variables
    x_sensor = solver.BoolVar('x_sensor')
    x_cooling = solver.BoolVar('x_cooling')
    x_power = solver.BoolVar('x_power')

    # Integer production quantity variables
    q_sensor = solver.IntVar(0, 12, 'q_sensor')
    q_cooling = solver.IntVar(0, 19, 'q_cooling')
    q_power = solver.IntVar(0, 17, 'q_power')

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(q_sensor, 21)
    objective.SetCoefficient(q_cooling, 29)
    objective.SetCoefficient(q_power, 29)
    objective.SetCoefficient(x_sensor, -107)
    objective.SetCoefficient(x_cooling, -94)
    objective.SetCoefficient(x_power, -52)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(5 * q_sensor + 4 * q_cooling + 3 * q_power <= 119)

    # Production activation constraints
    solver.Add(q_sensor <= 12 * x_sensor)
    solver.Add(q_cooling <= 19 * x_cooling)
    solver.Add(q_power <= 17 * x_power)

    # Solve the problem
    status = solver.Solve()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value()
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_production_planning()

