def solve_assignment_problem():
    # Step 1: Problem Description
    # Assign 4 tasks to 4 workers with minimum total cost

    # Step 2: Sets and Parameters
    workers = ['Casey', 'Finley', 'Drew', 'Bailey']
    tasks = ['routing audit', 'order batching', 'line inspection', 'inventory sync']

    # Cost matrix: c[i][j] = cost of worker i doing task j
    cost_matrix = [
        [14, 26, 23, 20],  # Casey
        [27, 27, 25, 10],  # Finley
        [11, 26, 10, 28],  # Drew
        [10, 13, 22, 27]   # Bailey
    ]

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i in range(len(workers)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(workers)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], cost_matrix[i][j])
    objective.SetMinimization()

    # Step 5: Constraints
    # Each task must be assigned to exactly one worker
    for j in range(len(tasks)):
        constraint = solver.Constraint(1, 1)
        for i in range(len(workers)):
            constraint.SetCoefficient(x[i, j], 1)

    # Each worker must be assigned to exactly one task
    for i in range(len(workers)):
        constraint = solver.Constraint(1, 1)
        for j in range(len(tasks)):
            constraint.SetCoefficient(x[i, j], 1)

    # Step 6: Solve the problem
    status = solver.Solve()

    # Step 7: Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = []
        for i in range(len(workers)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    assignment.append({
                        'worker': workers[i],
                        'task': tasks[j],
                        'cost': cost_matrix[i][j]
                    })
    else:
        total_cost = None
        assignment = None

    # Step 8: Output result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

