import json

def main():
    # Define the cost matrix
    # Rows: Casey, Bailey, Drew, Alex
    # Columns: order batching, inventory sync, routing audit, line inspection
    cost_matrix = [
        [9, 17, 23, 13],    # Casey
        [24, 10, 22, 23],   # Bailey
        [21, 8, 14, 26],    # Drew
        [27, 23, 12, 16]    # Alex
    ]

    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define decision variables
    n = len(cost_matrix)  # Number of people/tasks
    x = {}
    for i in range(n):
        for j in range(n):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for i in range(n):
        for j in range(n):
            objective.SetCoefficient(x[i, j], cost_matrix[i][j])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one person
    for j in range(n):
        solver.Add(sum(x[i, j] for i in range(n)) == 1)

    # Constraints: each person assigned exactly one task
    for i in range(n):
        solver.Add(sum(x[i, j] for j in range(n)) == 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = []
        for i in range(n):
            for j in range(n):
                if x[i, j].solution_value() > 0.5:
                    assignment.append((i, j))

        # Map indices to names
        people = ['Casey', 'Bailey', 'Drew', 'Alex']
        tasks = ['order batching', 'inventory sync', 'routing audit', 'line inspection']

        print(f"Optimal assignment found with total cost: {total_cost}")
        print("Assignments:")
        for i, j in assignment:
            print(f"{people[i]} -> {tasks[j]}")
    else:
        print("No optimal solution found")

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
