import json

def solve_resource_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'PrimeSteel')
    x2 = solver.IntVar(0, solver.infinity(), 'AeroFoam')
    x3 = solver.IntVar(0, solver.infinity(), 'EcoFuel')
    x4 = solver.IntVar(0, solver.infinity(), 'BioResin')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 40)
    objective.SetCoefficient(x2, 24)
    objective.SetCoefficient(x3, 44)
    objective.SetCoefficient(x4, 43)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(3 * x1 + 3 * x2 + 2 * x3 + x4 <= 54)

    # Raw material constraint
    solver.Add(2 * x1 + x2 + 5 * x3 + x4 <= 57)

    # Skilled labor constraint
    solver.Add(6 * x1 + 5 * x2 + 2 * x3 + 2 * x4 <= 74)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"PrimeSteel: {x1.solution_value()}")
        print(f"AeroFoam: {x2.solution_value()}")
        print(f"EcoFuel: {x3.solution_value()}")
        print(f"BioResin: {x4.solution_value()}")
        print(f"Total profit: {objective.Value()}")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
