import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('CBC')

    # Decision variables
    # Production quantities (integer)
    x_B = solver.IntVar(0, 8, 'x_B')  # battery packs
    x_S = solver.IntVar(0, 13, 'x_S')  # sensor kits
    x_C = solver.IntVar(0, 12, 'x_C')  # cooling racks
    x_P = solver.IntVar(0, 17, 'x_P')  # power modules

    # Activation variables (binary)
    y_B = solver.BoolVar('y_B')  # battery packs
    y_S = solver.BoolVar('y_S')  # sensor kits
    y_C = solver.BoolVar('y_C')  # cooling racks
    y_P = solver.BoolVar('y_P')  # power modules

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_B, 31)
    objective.SetCoefficient(x_S, 26)
    objective.SetCoefficient(x_C, 26)
    objective.SetCoefficient(x_P, 28)
    objective.SetCoefficient(y_B, -83)
    objective.SetCoefficient(y_S, -59)
    objective.SetCoefficient(y_C, -83)
    objective.SetCoefficient(y_P, -90)
    objective.SetMaximization()

    # Constraints
    # 1. Production time constraint
    solver.Add(3*x_B + 2*x_S + 3*x_C + 3*x_P <= 62)

    # 2. Production capacity constraints (already handled in variable definition)

    # 3. Activation constraints
    solver.Add(x_B <= 8*y_B)
    solver.Add(x_S <= 13*y_S)
    solver.Add(x_C <= 12*y_C)
    solver.Add(x_P <= 17*y_P)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == solver.OPTIMAL:
        objective_value = objective.Value()
        result = {
            "status": "OPTIMAL",
            "objective_value": objective_value,
            "production": {
                "battery_packs": int(x_B.solution_value()),
                "sensor_kits": int(x_S.solution_value()),
                "cooling_racks": int(x_C.solution_value()),
                "power_modules": int(x_P.solution_value())
            },
            "activation": {
                "battery_packs": int(y_B.solution_value()),
                "sensor_kits": int(y_S.solution_value()),
                "cooling_racks": int(y_C.solution_value()),
                "power_modules": int(y_P.solution_value())
            }
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

