    x_eco_fuel = solver.NumVar(0, solver.infinity(), 'x_eco_fuel')
    x_aero_foam = solver.NumVar(0, solver.infinity(), 'x_aero_foam')
    x_flex_circuit = solver.NumVar(0, solver.infinity(), 'x_flex_circuit')
    x_bio_resin = solver.NumVar(0, solver.infinity(), 'x_bio_resin')

