    objective.SetCoefficient(x_eco_fuel, 30)
    objective.SetCoefficient(x_aero_foam, 38)
    objective.SetCoefficient(x_flex_circuit, 26)
    objective.SetCoefficient(x_bio_resin, 27)
    objective.SetMaximization()

