    x_control = solver.IntVar(0, 19, 'x_control')
    x_battery = solver.IntVar(0, 9, 'x_battery')

    y_sensor = solver.BoolVar('y_sensor')
    y_control = solver.BoolVar('y_control')
    y_battery = solver.BoolVar('y_battery')

