    objective = solver.Objective()
    objective.SetCoefficient(x_sensor, 31)
    objective.SetCoefficient(x_control, 21)
    objective.SetCoefficient(x_battery, 30)
    objective.SetCoefficient(y_sensor, -84)
    objective.SetCoefficient(y_control, -83)
    objective.SetCoefficient(y_battery, -103)
