def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 14, 'x_S')  # sensor kits quantity
    x_P = solver.IntVar(0, 9, 'x_P')   # power modules quantity
    x_C = solver.IntVar(0, 10, 'x_C')  # control units quantity

    y_S = solver.BoolVar('y_S')  # sensor kits activation
    y_P = solver.BoolVar('y_P')  # power modules activation
    y_C = solver.BoolVar('y_C')  # control units activation

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 29)
    objective.SetCoefficient(x_P, 25)
    objective.SetCoefficient(x_C, 21)
    objective.SetCoefficient(y_S, -73)
    objective.SetCoefficient(y_P, -49)
    objective.SetCoefficient(y_C, -110)
    objective.SetMaximization()

    # Constraints
    # Total working hours constraint
    solver.Add(2 * x_S + 2 * x_P + 3 * x_C <= 46)

    # Production capacity constraints
    solver.Add(x_S <= 14)
    solver.Add(x_P <= 9)
    solver.Add(x_C <= 10)

    # Activation constraints
    solver.Add(x_S <= 14 * y_S)
    solver.Add(x_P <= 9 * y_P)
    solver.Add(x_C <= 10 * y_C)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x_S": x_S.solution_value(),
            "x_P": x_P.solution_value(),
            "x_C": x_C.solution_value(),
            "y_S": y_S.solution_value(),
            "y_P": y_P.solution_value(),
            "y_C": y_C.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

