def solve_production_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'SmartGlass')
    x2 = solver.IntVar(0, solver.infinity(), 'EcoFuel')
    x3 = solver.IntVar(0, solver.infinity(), 'BioResin')
    x4 = solver.IntVar(0, solver.infinity(), 'PrimeSteel')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 26)
    objective.SetCoefficient(x2, 32)
    objective.SetCoefficient(x3, 40)
    objective.SetCoefficient(x4, 31)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(2 * x1 + 2 * x2 + 3 * x3 + 3 * x4 <= 61)

    # Raw material constraint
    solver.Add(5 * x1 + 5 * x2 + 6 * x3 + 6 * x4 <= 114)

    # Skilled labor constraint
    solver.Add(2 * x1 + 3 * x2 + 1 * x3 + 6 * x4 <= 61)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"SmartGlass: {x1.solution_value()}")
        print(f"EcoFuel: {x2.solution_value()}")
        print(f"BioResin: {x3.solution_value()}")
        print(f"PrimeSteel: {x4.solution_value()}")
        print(f"Total profit: {objective.Value()}")
