def main():
    # Step 1: Problem Description
    # Assign 4 tasks to 4 team members to minimize total cost

    # Step 2: Sets and Parameters
    members = ['Drew', 'Finley', 'Emery', 'Casey']
    tasks = ['line inspection', 'order batching', 'routing audit', 'inventory sync']

    # Cost matrix: c[i][j] = cost of assigning member i to task j
    cost_matrix = [
        [25, 20, 18, 12],  # Drew
        [10, 12, 20, 18],  # Finley
        [9, 8, 21, 12],    # Emery
        [24, 18, 17, 14]   # Casey
    ]

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], cost_matrix[i][j])
    objective.SetMinimization()

    # Step 5: Constraints
    # Each task must be assigned to exactly one person
    for j in range(len(tasks)):
        solver.Add(sum(x[i, j] for i in range(len(members))) == 1)

    # Each person must be assigned exactly one task
    for i in range(len(members)):
        solver.Add(sum(x[i, j] for j in range(len(tasks))) == 1)

    # Step 6: Mathematical Model Summary
    # Minimize Σ Σ c_ij * x_ij
    # Subject to:
    # - Σ x_ij = 1 for each task j
    # - Σ x_ij = 1 for each person i
    # - x_ij ∈ {0, 1} for all i, j

    # Step 7: Nonlinear Relationships
    # No nonlinear relationships in this linear assignment problem

    # Step 8: Final Model and Implementation Considerations
    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print("Optimal assignment found:")
        total_cost = 0
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    print(f"{members[i]} assigned to {tasks[j]} with cost {cost_matrix[i][j]}")
                    total_cost += cost_matrix[i][j]
        print(f"Total cost: {total_cost}")
    else:
        print("No optimal solution found")

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

