from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 14, 'x1')  # sensor kits quantity
    x2 = solver.IntVar(0, 20, 'x2')  # cooling racks quantity
    x3 = solver.IntVar(0, 18, 'x3')  # power modules quantity

    y1 = solver.BoolVar('y1')  # sensor kits activation
    y2 = solver.BoolVar('y2')  # cooling racks activation
    y3 = solver.BoolVar('y3')  # power modules activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 22)
    objective.SetCoefficient(x2, 21)
    objective.SetCoefficient(x3, 23)
    objective.SetCoefficient(y1, -97)
    objective.SetCoefficient(y2, -62)
    objective.SetCoefficient(y3, -110)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(3 * x1 + 4 * x2 + 2 * x3 <= 92)

