import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Item data: name, weight, value
    items = [
        ('backup battery', 5, 14),
        ('portable scanner', 4, 27),
        ('sensor pod', 6, 18),
        ('relay box', 7, 13),
        ('field router', 9, 45)
    ]

    # Knapsack capacity
    capacity = 14

    # Create decision variables
    x = {}
    for i, (name, weight, value) in enumerate(items):
        x[i] = solver.BoolVar(f'x_{i}')

    # Objective function: maximize total value
    objective = solver.Objective()
    for i, (name, weight, value) in enumerate(items):
        objective.SetCoefficient(x[i], value)
    objective.SetMaximization()

    # Weight constraint
    weight_constraint = solver.Constraint(0, capacity)
    for i, (name, weight, value) in enumerate(items):
        weight_constraint.SetCoefficient(x[i], weight)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    for i, (name, weight, value) in enumerate(items):
        if x[i].solution_value() > 0.5:
            selected_items.append(name)
            total_value += value
            total_weight += weight

    # Print results
    print(f"Status: {status}")
    print(f"Selected items: {selected_items}")
    print(f"Total value: {total_value}")
    print(f"Total weight: {total_weight}")

    # Return result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_knapsack()

