def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_CU = solver.IntVar(0, 18, 'x_CU')  # Control units quantity
    x_BP = solver.IntVar(0, 13, 'x_BP')  # Battery packs quantity
    x_SK = solver.IntVar(0, 9, 'x_SK')   # Sensor kits quantity

    y_CU = solver.BoolVar('y_CU')  # Control units activation
    y_BP = solver.BoolVar('y_BP')  # Battery packs activation
    y_SK = solver.BoolVar('y_SK')  # Sensor kits activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_CU, 27)
    objective.SetCoefficient(x_BP, 25)
    objective.SetCoefficient(x_SK, 34)
    objective.SetCoefficient(y_CU, -89)
    objective.SetCoefficient(y_BP, -61)
    objective.SetCoefficient(y_SK, -63)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(6 * x_CU + 3 * x_BP + 6 * x_SK <= 97)

    # Production quantity constraints (linked to activation variables)
    solver.Add(x_CU <= 18 * y_CU)
    solver.Add(x_BP <= 13 * y_BP)
    solver.Add(x_SK <= 9 * y_SK)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = objective.Value()
        result = {
            "status": "OPTIMAL",
            "objective_value": objective_value,
            "x_CU": x_CU.solution_value(),
            "x_BP": x_BP.solution_value(),
