from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['CU', 'PM', 'SK', 'BP']

    # Parameters
    unit_profit = {'CU': 22, 'PM': 21, 'SK': 31, 'BP': 32}
    fixed_cost = {'CU': 76, 'PM': 48, 'SK': 78, 'BP': 86}
    labor_hours = {'CU': 6, 'PM': 2, 'SK': 5, 'BP': 6}
    max_capacity = {'CU': 15, 'PM': 13, 'SK': 15, 'BP': 12}
    total_labor = 170

    # Decision variables
    x = {}  # Production quantities (integer)
    y = {}  # Activation variables (binary)

    for product in products:
        x[product] = solver.IntVar(0, max_capacity[product], f'x_{product}')
        y[product] = solver.BoolVar(f'y_{product}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for product in products:
        objective.SetCoefficient(x[product], unit_profit[product])
        objective.SetCoefficient(y[product], -fixed_cost[product])
    objective.SetMaximization()

    # Constraints
    # Labor constraint
    labor_constraint = solver.Constraint(0, total_labor)
    for product in products:
        labor_constraint.SetCoefficient(x[product], labor_hours[product])

    # Activation constraints
    for product in products:
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(x[product], 1)
        activation_constraint.SetCoefficient(y[product], -max_capacity[product])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            'status': 'OPTIMAL',
            'objective_value': objective.Value(),
            'production': {p: x[p].solution_value() for p in products},
            'activation': {p: y[p].solution_value() for p in products}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': None,
            'production': {p: 0 for p in products},
            'activation': {p: 0 for p in products}
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

