from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 12, 'x_S')  # sensor kits quantity
    x_C = solver.IntVar(0, 11, 'x_C')  # cooling racks quantity
    x_P = solver.IntVar(0, 10, 'x_P')  # power modules quantity
    y_S = solver.BoolVar('y_S')        # sensor kits activation
    y_C = solver.BoolVar('y_C')        # cooling racks activation
    y_P = solver.BoolVar('y_P')        # power modules activation

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 20)
    objective.SetCoefficient(x_C, 21)
    objective.SetCoefficient(x_P, 25)
    objective.SetCoefficient(y_S, -72)
    objective.SetCoefficient(y_C, -91)
    objective.SetCoefficient(y_P, -96)
    objective.SetMaximization()

    # Constraints
    # Production time constraint
    solver.Add(5 * x_S + 5 * x_C + 5 * x_P <= 92)

    # Linking constraints
    solver.Add(x_S <= 12 * y_S)
    solver.Add(x_C <= 11 * y_C)
    solver.Add(x_P <= 10 * y_P)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x_S": x_S.solution_value(),
            "x_C": x_C.solution_value(),
            "x_P": x_P.solution_value(),
            "y_S": y_S.solution_value(),
            "y_C": y_C.solution_value(),
            "y_P": y_P.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

