from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['power_modules', 'battery_packs', 'control_units', 'cooling_racks']
    num_products = len(products)

    # Parameters
    profit_per_unit = [31, 29, 24, 28]
    fixed_setup_cost = [77, 97, 58, 60]
    labor_per_unit = [2, 2, 2, 5]
    max_production = [18, 12, 15, 19]
    total_labor_limit = 128

    # Decision variables
    x = []
    y = []
    for i in range(num_products):
        # Production quantity (integer)
        x_i = solver.IntVar(0, max_production[i], f'x_{i}')
        x.append(x_i)

        # Activation variable (binary)
        y_i = solver.BoolVar(f'y_{i}')
        y.append(y_i)

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(num_products):
        objective.SetCoefficient(x[i], profit_per_unit[i])
        objective.SetCoefficient(y[i], -fixed_setup_cost[i])
    objective.SetMaximization()

    # Constraints
    # 1. Labor constraint
    labor_constraint = solver.Constraint(0, total_labor_limit)
    for i in range(num_products):
        labor_constraint.SetCoefficient(x[i], labor_per_unit[i])

    # 2. Activation constraints
    for i in range(num_products):
        solver.Add(x[i] <= max_production[i] * y[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value()
    }

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

