from ortools.linear_solver import pywraplp
import json

def solve_resource_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define decision variables
    x_flex = solver.NumVar(0, solver.infinity(), 'x_flex')
    x_bio = solver.NumVar(0, solver.infinity(), 'x_bio')
    x_prime = solver.NumVar(0, solver.infinity(), 'x_prime')
    x_eco = solver.NumVar(0, solver.infinity(), 'x_eco')
    x_aero = solver.NumVar(0, solver.infinity(), 'x_aero')

    # Define objective function
    objective = solver.Objective()
    objective.SetCoefficient(x_flex, 42)
    objective.SetCoefficient(x_bio, 27)
    objective.SetCoefficient(x_prime, 28)
    objective.SetCoefficient(x_eco, 33)
    objective.SetCoefficient(x_aero, 48)
    objective.SetMaximization()

    # Add constraints
    # Machine hours constraint
    solver.Add(6 * x_flex + 1 * x_bio + 1 * x_prime + 6 * x_eco + 1 * x_aero <= 72)

    # Raw material constraint
    solver.Add(6 * x_flex + 3 * x_bio + 4 * x_prime + 5 * x_eco + 6 * x_aero <= 140)

    # Skilled labor constraint
    solver.Add(5 * x_flex + 4 * x_bio + 2 * x_prime + 4 * x_eco + 2 * x_aero <= 103)

    # Solve the problem
    status = solver.Solve()

    # Output results
    if status == pywraplp.Solver.OPTIMAL:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_resource_allocation()

