def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_cu = solver.IntVar(0, 13, 'x_cu')  # control units
    x_sk = solver.IntVar(0, 9, 'x_sk')   # sensor kits
    x_bp = solver.IntVar(0, 12, 'x_bp')  # battery packs

    y_cu = solver.BoolVar('y_cu')  # activation for control units
    y_sk = solver.BoolVar('y_sk')  # activation for sensor kits
    y_bp = solver.BoolVar('y_bp')  # activation for battery packs

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_cu, 30)
    objective.SetCoefficient(x_sk, 25)
    objective.SetCoefficient(x_bp, 33)
    objective.SetCoefficient(y_cu, -76)
    objective.SetCoefficient(y_sk, -62)
    objective.SetCoefficient(y_bp, -101)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(2 * x_cu + 3 * x_sk + 6 * x_bp <= 69)

    # Activation constraints
    solver.Add(x_cu <= 13 * y_cu)
    solver.Add(x_sk <= 9 * y_sk)
    solver.Add(x_bp <= 12 * y_bp)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": solver.Objective().Value(),
            "x_cu": x_cu.solution_value(),
            "x_sk": x_sk.solution_value(),
            "x_bp": x_bp.solution_value(),
            "y_cu": y_cu.solution_value(),
            "y_sk": y_sk.solution_value(),
            "y_bp": y_bp.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

