import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = {
        'battery': {'profit': 35, 'fixed_cost': 98, 'hours': 3, 'max': 18},
        'sensor': {'profit': 32, 'fixed_cost': 50, 'hours': 2, 'max': 9},
        'control': {'profit': 22, 'fixed_cost': 65, 'hours': 5, 'max': 16},
        'cooling': {'profit': 30, 'fixed_cost': 71, 'hours': 3, 'max': 15}
    }

    # Decision variables
    x = {}  # Production quantities
    y = {}  # Activation variables

    for name, params in products.items():
        x[name] = solver.IntVar(0, params['max'], f'x_{name}')
        y[name] = solver.BoolVar(f'y_{name}')

    # Objective function: maximize profit
    objective = solver.Objective()
    for name, params in products.items():
        objective.SetCoefficient(x[name], params['profit'])
        objective.SetCoefficient(y[name], -params['fixed_cost'])
    objective.SetMaximization()

    # Labor hour constraint
    labor_constraint = solver.Constraint(0, 133)
    for name, params in products.items():
        labor_constraint.SetCoefficient(x[name], params['hours'])

    # Activation constraints
    for name, params in products.items():
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(x[name], 1)
        activation_constraint.SetCoefficient(y[name], -params['max'])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value(),
        'production': {name: x[name].solution_value() for name in products},
        'activation': {name: y[name].solution_value() for name in products}
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

