import json

def solve_assignment_problem():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define the team members and tasks
    team_members = ['Bailey', 'Emery', 'Finley', 'Drew']
    tasks = ['inventory sync', 'line inspection', 'order batching', 'routing audit']

    # Cost matrix
    costs = {
        'Bailey': [19, 28, 12, 8],
        'Emery': [20, 10, 13, 25],
        'Finley': [27, 20, 27, 23],
        'Drew': [22, 26, 25, 12]
    }

    # Create decision variables
    x = {}
    for i, person in enumerate(team_members):
        for j, task in enumerate(tasks):
            x[(person, task)] = solver.IntVar(0, 1, f'x_{person}_{task}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for i, person in enumerate(team_members):
        for j, task in enumerate(tasks):
            objective.SetCoefficient(x[(person, task)], costs[person][j])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one person
    for j, task in enumerate(tasks):
        constraint = solver.Constraint(1, 1)
        for i, person in enumerate(team_members):
            constraint.SetCoefficient(x[(person, task)], 1)

    # Constraints: each person assigned to exactly one task
    for i, person in enumerate(team_members):
        constraint = solver.Constraint(1, 1)
        for j, task in enumerate(tasks):
            constraint.SetCoefficient(x[(person, task)], 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for i, person in enumerate(team_members):
            for j, task in enumerate(tasks):
                if x[(person, task)].solution_value() > 0.5:
                    assignment[person] = task
                    break
    else:
        total_cost = None
        assignment = None

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

