from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 20, 'x1')  # battery packs quantity
    x2 = solver.IntVar(0, 12, 'x2')  # control units quantity
    x3 = solver.IntVar(0, 17, 'x3')  # cooling racks quantity

    y1 = solver.BoolVar('y1')  # battery packs activation
    y2 = solver.BoolVar('y2')  # control units activation
    y3 = solver.BoolVar('y3')  # cooling racks activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 35)
    objective.SetCoefficient(x2, 22)
    objective.SetCoefficient(x3, 18)
    objective.SetCoefficient(y1, -104)
    objective.SetCoefficient(y2, -57)
    objective.SetCoefficient(y3, -105)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(2 * x1 + 2 * x2 + 3 * x3 <= 73)

    # Production capacity constraints
    solver.Add(x1 <= 20)
    solver.Add(x2 <= 12)
    solver.Add(x3 <= 17)

    # Linking constraints
    solver.Add(x1 <= 20 * y1)
    solver.Add(x2 <= 12 * y2)
    solver.Add(x3 <= 17 * y3)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = objective.Value()
        result = {
            "status": "OPTIMAL",
            "objective_value": objective_value
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

