        constraint = solver.Constraint(1, 1)
        for i in members:
            constraint.SetCoefficient(x[(i, j)], 1)

    # Constraints: each person assigned to exactly one task
    for i in members:
        constraint = solver.Constraint(1, 1)
        for j in tasks:
            constraint.SetCoefficient(x[(i, j)], 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for i in members:
            for j in tasks:
                if x[(i, j)].solution_value() > 0.5:
                    assignment[i] = j
                    break
    else:
        total_cost = None
        assignment = None

    # Print result
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

