def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 8, 'x1')  # battery packs quantity
    x2 = solver.IntVar(0, 8, 'x2')  # sensor kits quantity
    x3 = solver.IntVar(0, 10, 'x3') # control units quantity

    y1 = solver.BoolVar('y1')  # battery packs activation
    y2 = solver.BoolVar('y2')  # sensor kits activation
    y3 = solver.BoolVar('y3')  # control units activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 30)
    objective.SetCoefficient(x2, 28)
    objective.SetCoefficient(x3, 19)
    objective.SetCoefficient(y1, -87)
    objective.SetCoefficient(y2, -85)
    objective.SetCoefficient(y3, -90)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(4 * x1 + 6 * x2 + 5 * x3 <= 85)

    # Activation constraints
    solver.Add(x1 <= 8 * y1)
    solver.Add(x2 <= 8 * y2)
    solver.Add(x3 <= 10 * y3)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x1": x1.solution_value(),
            "x2": x2.solution_value(),
            "x3": x3.solution_value(),
            "y1": y1.solution_value(),
            "y2": y2.solution_value(),
            "y3": y3.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

