    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_s = solver.IntVar(0, 15, 'x_s')  # sensor kits
    x_c = solver.IntVar(0, 18, 'x_c')  # control units
    x_b = solver.IntVar(0, 15, 'x_b')  # battery packs

    y_s = solver.BoolVar('y_s')  # activation for sensor kits
    y_c = solver.BoolVar('y_c')  # activation for control units
    y_b = solver.BoolVar('y_b')  # activation for battery packs

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_s, 26)
    objective.SetCoefficient(x_c, 26)
    objective.SetCoefficient(x_b, 33)
    objective.SetCoefficient(y_s, -54)
    objective.SetCoefficient(y_c, -64)
    objective.SetCoefficient(y_b, -54)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(3 * x_s + 2 * x_c + 5 * x_b <= 107)

    # Production limits (already handled in variable definitions)

    # Activation constraints
    solver.Add(x_s <= 15 * y_s)
    solver.Add(x_c <= 18 * y_c)
    solver.Add(x_b <= 15 * y_b)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
        print(f"Sensor kits: {x_s.solution_value()}, Activated: {y_s.solution_value()}")
