from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['cooling', 'sensor', 'control', 'power']
    unit_profit = [23, 23, 18, 20]
    setup_cost = [71, 100, 46, 101]
    labor_per_unit = [5, 2, 2, 3]
    max_capacity = [11, 10, 13, 12]

    # Decision variables
    x = []  # Production quantities
    y = []  # Activation variables

    for i in range(len(products)):
        # Integer production variables
        x_i = solver.IntVar(0, max_capacity[i], f'x_{products[i]}')
        x.append(x_i)

        # Binary activation variables
        y_i = solver.BoolVar(f'y_{products[i]}')
        y.append(y_i)

    # Objective function: maximize net profit
    objective = solver.Objective()
    for i in range(len(products)):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -setup_cost[i])
    objective.SetMaximization()

    # Constraints
    # 1. Labor constraint
    labor_constraint = solver.Constraint(0, 70)
    for i in range(len(products)):
        labor_constraint.SetCoefficient(x[i], labor_per_unit[i])

    # 2. Activation constraints
    for i in range(len(products)):
        solver.Add(x[i] <= max_capacity[i] * y[i])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            'status': 'OPTIMAL',
            'objective_value': objective.Value(),
            'production': {products[i]: x[i].solution_value() for i in range(len(products))},
            'activation': {products[i]: y[i].solution_value() for i in range(len(products))}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': 0,
            'production': {products[i]: 0 for i in range(len(products))},
            'activation': {products[i]: 0 for i in range(len(products))}
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_production_planning()

