def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_aero = solver.NumVar(0, solver.infinity(), 'x_aero')
    x_smart = solver.NumVar(0, solver.infinity(), 'x_smart')
    x_flex = solver.NumVar(0, solver.infinity(), 'x_flex')
    x_bio = solver.NumVar(0, solver.infinity(), 'x_bio')

