    objective = solver.Objective()
    objective.SetCoefficient(x_aero, 30)
    objective.SetCoefficient(x_smart, 21)
    objective.SetCoefficient(x_flex, 42)
    objective.SetCoefficient(x_bio, 42)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(x_aero + x_smart + x_flex + 5 * x_bio <= 49)

    # Raw material constraint
    solver.Add(6 * x_aero + 5 * x_smart + 6 * x_flex + 2 * x_bio <= 92)

