import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define items with their values and weights
    items = [
        ('edge_server', 39, 5),
        ('field_router', 14, 10),
        ('backup_battery', 20, 9),
        ('sensor_pod', 37, 7),
        ('relay_box', 38, 3),
        ('thermal_camera', 20, 4)
    ]

    # Capacity of the knapsack
    capacity = 22

    # Create binary variables for each item
    x = {}
    for name, value, weight in items:
        x[name] = solver.BoolVar(name)

    # Objective: maximize total value
    objective = solver.Objective()
    for name, value, weight in items:
        objective.SetCoefficient(x[name], value)
    objective.SetMaximization()

    # Constraint: total weight <= capacity
    weight_constraint = solver.Constraint(0, capacity)
    for name, value, weight in items:
        weight_constraint.SetCoefficient(x[name], weight)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    for name, value, weight in items:
        if x[name].solution_value() > 0.5:
            selected_items.append(name)
            total_value += value
            total_weight += weight

    # Print results
    print("Selected items:", selected_items)
    print("Total value:", total_value)
    print("Total weight:", total_weight)

    # Return result in required format
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

