def solve_assignment_problem():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('CBC')

    # Define the team members and tasks
    team_members = ['Drew', 'Finley', 'Bailey', 'Alex']
    tasks = ['inventory sync', 'routing audit', 'order batching', 'line inspection']

    # Cost matrix
    costs = {
        'Drew': {'inventory sync': 28, 'routing audit': 21, 'order batching': 19, 'line inspection': 27},
        'Finley': {'inventory sync': 12, 'routing audit': 12, 'order batching': 16, 'line inspection': 26},
        'Bailey': {'inventory sync': 19, 'routing audit': 22, 'order batching': 21, 'line inspection': 22},
        'Alex': {'inventory sync': 27, 'routing audit': 16, 'order batching': 15, 'line inspection': 24}
    }

    # Create decision variables
    x = {}
    for member in team_members:
        for task in tasks:
            x[member, task] = solver.IntVar(0, 1, f'x_{member}_{task}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for member in team_members:
        for task in tasks:
            objective.SetCoefficient(x[member, task], costs[member][task])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one person
    for task in tasks:
        constraint = solver.Constraint(1, 1)
        for member in team_members:
            constraint.SetCoefficient(x[member, task], 1)

    # Constraints: each person assigned to exactly one task
    for member in team_members:
        constraint = solver.Constraint(1, 1)
        for task in tasks:
            constraint.SetCoefficient(x[member, task], 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for member in team_members:
            for task in tasks:
                if x[member, task].solution_value() > 0.5:
                    assignment[member] = task
                    break

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

