    y_battery = solver.BoolVar('y_battery')
    x_sensor = solver.IntVar(0, 20, 'x_sensor')
    y_sensor = solver.BoolVar('y_sensor')
    x_control = solver.IntVar(0, 8, 'x_control')
    y_control = solver.BoolVar('y_control')

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_battery, 28)
    objective.SetCoefficient(x_sensor, 19)
    objective.SetCoefficient(x_control, 35)
    objective.SetCoefficient(y_battery, -66)
    objective.SetCoefficient(y_sensor, -99)
    objective.SetCoefficient(y_control, -47)
    objective.SetMaximization()

    # Constraints
