    solver.Add(6 * x_battery + 6 * x_sensor + 3 * x_control <= 103)

    # Production quantity constraints
    solver.Add(x_battery <= 12)
    solver.Add(x_sensor <= 20)
    solver.Add(x_control <= 8)

    # Activation constraints
    solver.Add(x_battery <= 12 * y_battery)
    solver.Add(x_sensor <= 20 * y_sensor)
    solver.Add(x_control <= 8 * y_control)

    # Solve the problem
    status = solver.Solve()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value()
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

