from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = {
        'power': {'profit': 28, 'setup': 110, 'time': 2, 'capacity': 11},
        'battery': {'profit': 30, 'setup': 97, 'time': 3, 'capacity': 17},
        'control': {'profit': 20, 'setup': 60, 'time': 5, 'capacity': 16}
    }

    # Decision variables
    x = {}  # Production quantities
    y = {}  # Activation variables

    for p in products:
        x[p] = solver.IntVar(0, products[p]['capacity'], f'x_{p}')
        y[p] = solver.BoolVar(f'y_{p}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for p in products:
        objective.SetCoefficient(x[p], products[p]['profit'])
        objective.SetCoefficient(y[p], -products[p]['setup'])
    objective.SetMaximization()

    # Constraints
    # 1. Total working hours constraint
    solver.Add(2 * x['power'] + 3 * x['battery'] + 5 * x['control'] <= 84)

    # 2. Activation constraints
    solver.Add(x['power'] <= 11 * y['power'])
    solver.Add(x['battery'] <= 17 * y['battery'])
    solver.Add(x['control'] <= 16 * y['control'])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_profit = objective.Value()
        result = {
            'status': 'OPTIMAL',
            'objective_value': total_profit,
            'production': {p: int(x[p].solution_value()) for p in products},
            'activation': {p: int(y[p].solution_value()) for p in products}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': 0,
            'production': {p: 0 for p in products},
            'activation': {p: 0 for p in products}
        }

    return result

