    x1 = solver.IntVar(0, solver.infinity(), 'AeroFoam')
    x2 = solver.IntVar(0, solver.infinity(), 'EcoFuel')
    x3 = solver.IntVar(0, solver.infinity(), 'SmartGlass')

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 18)
    objective.SetCoefficient(x2, 36)
    objective.SetCoefficient(x3, 48)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    machine_hours = solver.Constraint(0, 92)
    machine_hours.SetCoefficient(x1, 5)
    machine_hours.SetCoefficient(x2, 6)
    machine_hours.SetCoefficient(x3, 4)

    # Raw material constraint
    raw_material = solver.Constraint(0, 33)
    raw_material.SetCoefficient(x1, 3)
    raw_material.SetCoefficient(x2, 3)
    raw_material.SetCoefficient(x3, 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
