def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 8, 'x_S')  # sensor kits
    x_C = solver.IntVar(0, 12, 'x_C')  # control units
    x_P = solver.IntVar(0, 20, 'x_P')  # power modules
    x_R = solver.IntVar(0, 16, 'x_R')  # cooling racks

    y_S = solver.BoolVar('y_S')  # activation for sensor kits
    y_C = solver.BoolVar('y_C')  # activation for control units
    y_P = solver.BoolVar('y_P')  # activation for power modules
    y_R = solver.BoolVar('y_R')  # activation for cooling racks

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 32)
    objective.SetCoefficient(x_C, 34)
    objective.SetCoefficient(x_P, 29)
    objective.SetCoefficient(x_R, 25)
    objective.SetCoefficient(y_S, -101)
    objective.SetCoefficient(y_C, -58)
    objective.SetCoefficient(y_P, -93)
    objective.SetCoefficient(y_R, -84)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(3 * x_S + 5 * x_C + 2 * x_P + 5 * x_R <= 95)

    # Activation constraints
    solver.Add(x_S <= 8 * y_S)
    solver.Add(x_C <= 12 * y_C)
    solver.Add(x_P <= 20 * y_P)
    solver.Add(x_R <= 16 * y_R)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print("Optimal solution found:")
        print(f"Sensor kits: {x_S.solution_value()}, Control units: {x_C.solution_value()}")
        print(f"Power modules: {x_P.solution_value()}, Cooling racks: {x_R.solution_value()}")
        print(f"Total profit: {objective.Value()}")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("No optimal solution found.")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

