from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = {
        'CR': {'profit': 25, 'setup_cost': 103, 'time': 2, 'max_quantity': 13},
        'BP': {'profit': 23, 'setup_cost': 46, 'time': 2, 'max_quantity': 10},
        'SK': {'profit': 26, 'setup_cost': 93, 'time': 2, 'max_quantity': 17},
        'PM': {'profit': 33, 'setup_cost': 100, 'time': 2, 'max_quantity': 14}
    }

    # Decision variables
    x = {}
    y = {}
    for product, params in products.items():
        x[product] = solver.IntVar(0, params['max_quantity'], f'x_{product}')
        y[product] = solver.BoolVar(f'y_{product}')

    # Objective function: maximize net profit
    objective = solver.Objective()
    for product, params in products.items():
        objective.SetCoefficient(x[product], params['profit'])
        objective.SetCoefficient(y[product], -params['setup_cost'])
    objective.SetMaximization()

    # Constraints
    # Total working hours constraint
    solver.Add(2 * x['CR'] + 2 * x['BP'] + 2 * x['SK'] + 2 * x['PM'] <= 65)

    # Production quantity constraints with activation variables
    for product, params in products.items():
        solver.Add(x[product] <= params['max_quantity'] * y[product])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            'status': 'OPTIMAL',
            'objective_value': objective.Value(),
            'production': {product: x[product].solution_value() for product in products},
            'activation': {product: y[product].solution_value() for product in products}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': 0,
            'production': {product: 0 for product in products},
            'activation': {product: 0 for product in products}
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_production_planning()

