import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Production quantities (integer)
    x1 = solver.IntVar(0, 18, 'x1')  # cooling racks
    x2 = solver.IntVar(0, 15, 'x2')  # control units
    x3 = solver.IntVar(0, 11, 'x3')  # sensor kits

    # Activation variables (binary)
    y1 = solver.BoolVar('y1')  # cooling racks
    y2 = solver.BoolVar('y2')  # control units
    y3 = solver.BoolVar('y3')  # sensor kits

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 29)
    objective.SetCoefficient(x2, 20)
    objective.SetCoefficient(x3, 27)
    objective.SetCoefficient(y1, -107)
    objective.SetCoefficient(y2, -76)
    objective.SetCoefficient(y3, -65)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(3 * x1 + 2 * x2 + 6 * x3 <= 104)

    # Production capacity constraints
    solver.Add(x1 <= 18)
    solver.Add(x2 <= 15)
    solver.Add(x3 <= 11)

    # Activation constraints
    solver.Add(x1 <= 18 * y1)
    solver.Add(x2 <= 15 * y2)
    solver.Add(x3 <= 11 * y3)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x1": x1.solution_value(),
            "x2": x2.solution_value(),
            "x3": x3.solution_value(),
            "y1": y1.solution_value(),
            "y2": y2.solution_value(),
            "y3": y3.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

