import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_cu = solver.IntVar(0, 18, 'x_cu')  # Control units production quantity
    x_pm = solver.IntVar(0, 13, 'x_pm')  # Power modules production quantity
    x_sk = solver.IntVar(0, 20, 'x_sk')  # Sensor kits production quantity

    y_cu = solver.BoolVar('y_cu')  # Control units activation
    y_pm = solver.BoolVar('y_pm')  # Power modules activation
    y_sk = solver.BoolVar('y_sk')  # Sensor kits activation

    # Objective function: Maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x_cu, 21)
    objective.SetCoefficient(x_pm, 29)
    objective.SetCoefficient(x_sk, 31)
    objective.SetCoefficient(y_cu, -68)
    objective.SetCoefficient(y_pm, -98)
    objective.SetCoefficient(y_sk, -58)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(5 * x_cu + 5 * x_pm + 3 * x_sk <= 124)

    # Production activation constraints
    solver.Add(x_cu <= 18 * y_cu)
    solver.Add(x_pm <= 13 * y_pm)
    solver.Add(x_sk <= 20 * y_sk)

