from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['power_modules', 'cooling_racks', 'battery_packs']

    # Parameters
    unit_profit = {'power_modules': 20, 'cooling_racks': 20, 'battery_packs': 36}
    fixed_cost = {'power_modules': 56, 'cooling_racks': 91, 'battery_packs': 71}
    unit_time = {'power_modules': 4, 'cooling_racks': 3, 'battery_packs': 2}
    max_production = {'power_modules': 20, 'cooling_racks': 11, 'battery_packs': 13}
    total_time = 93

    # Decision variables
    x = {}  # Production quantities
    y = {}  # Activation variables

    for product in products:
        x[product] = solver.IntVar(0, max_production[product], f'x_{product}')
        y[product] = solver.BoolVar(f'y_{product}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for product in products:
        objective.SetCoefficient(x[product], unit_profit[product])
        objective.SetCoefficient(y[product], -fixed_cost[product])
    objective.SetMaximization()

    # Constraints
    # 1. Labor time constraint
    solver.Add(sum(unit_time[product] * x[product] for product in products) <= total_time)

    # 2. Activation constraints (link x and y)
    for product in products:
        solver.Add(x[product] <= max_production[product] * y[product])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value(),
        'production': {product: x[product].solution_value() for product in products},
        'activation': {product: y[product].solution_value() for product in products}
    }

    return result

# Solve and print results
