from ortools.linear_solver import pywraplp
import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define items
    items = ['edge_server', 'sensor_pod', 'backup_battery', 'relay_box', 'portable_scanner']
    values = [33, 29, 29, 30, 32]
    weights = [4, 9, 9, 2, 9]
    capacity = 13

    # Create binary variables
    x = {}
    for i in range(len(items)):
        x[i] = solver.BoolVar(f'x_{i}')

    # Objective function: maximize total value
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Capacity constraint
    constraint = solver.Constraint(0, capacity)
    for i in range(len(items)):
        constraint.SetCoefficient(x[i], weights[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': objective.Value(),
        'selected_items': []
    }

    # Get selected items
    for i in range(len(items)):
        if x[i].solution_value() > 0.5:
            result['selected_items'].append(items[i])

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

