def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 9, 'x_S')  # sensor kits quantity
    x_B = solver.IntVar(0, 11, 'x_B')  # battery packs quantity
    x_P = solver.IntVar(0, 15, 'x_P')  # power modules quantity
    y_S = solver.BoolVar('y_S')  # sensor kits activation
    y_B = solver.BoolVar('y_B')  # battery packs activation
    y_P = solver.BoolVar('y_P')  # power modules activation

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 31)
    objective.SetCoefficient(x_B, 26)
    objective.SetCoefficient(x_P, 23)
    objective.SetCoefficient(y_S, -71)
    objective.SetCoefficient(y_B, -96)
    objective.SetCoefficient(y_P, -80)
    objective.SetMaximization()

    # Constraints
    # Total work hours constraint
    solver.Add(5 * x_S + 5 * x_B + 5 * x_P <= 101)

    # Activation constraints
    solver.Add(x_S <= 9 * y_S)
    solver.Add(x_B <= 11 * y_B)
    solver.Add(x_P <= 15 * y_P)

    # Solve the problem
    status = solver.Solve()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value()
    }

