from ortools.linear_solver import pywraplp
import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define items
    items = ['relay box', 'thermal camera', 'edge server', 'sensor pod', 'portable scanner']
    values = [12, 26, 43, 38, 33]
    weights = [4, 6, 8, 4, 4]
    capacity = 15
    num_items = len(items)

    # Decision variables
    x = [solver.BoolVar(f'x_{i}') for i in range(num_items)]

    # Objective function: maximize total value
    objective = solver.Objective()
    for i in range(num_items):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Weight capacity constraint
    constraint = solver.Constraint(0, capacity)
    for i in range(num_items):
        constraint.SetCoefficient(x[i], weights[i])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    if status == solver.OPTIMAL:
        for i in range(num_items):
            if x[i].solution_value() > 0.5:
                selected_items.append(items[i])
                total_value += values[i]
                total_weight += weights[i]

    # Print results
    print("Selected items:", selected_items)
    print("Total value:", total_value)
    print("Total weight:", total_weight)

    # Return result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_knapsack()

