    return {'status': _steporlm_status_name(status_value), 'objective_value': objective_value}

from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 18, 'x1')  # battery packs quantity
    x2 = solver.IntVar(0, 20, 'x2')  # cooling racks quantity
    x3 = solver.IntVar(0, 11, 'x3')  # power modules quantity

    y1 = solver.BoolVar('y1')  # battery packs activation
    y2 = solver.BoolVar('y2')  # cooling racks activation
    y3 = solver.BoolVar('y3')  # power modules activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 29)
    objective.SetCoefficient(x2, 27)
    objective.SetCoefficient(x3, 22)
    objective.SetCoefficient(y1, -54)
    objective.SetCoefficient(y2, -104)
    objective.SetCoefficient(y3, -82)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(4 * x1 + 2 * x2 + 4 * x3 <= 71)

    # Production capacity constraints
    solver.Add(x1 <= 18)
    solver.Add(x2 <= 20)
    solver.Add(x3 <= 11)

    # Activation constraints
    solver.Add(x1 <= 18 * y1)
    solver.Add(x2 <= 20 * y2)
    solver.Add(x3 <= 11 * y3)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = objective.Value()
        result = {"status": "OPTIMAL", "objective_value": objective_value}
    else:
        result = {"status": "INFEASIBLE", "objective_value": 0.0}

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

