from ortools.linear_solver import pywraplp
import json

def main():
    # Step 1: Problem Description
    # Assign 4 tasks to 4 members with minimum total cost

    # Step 2: Sets and Parameters
    members = ['Bailey', 'Casey', 'Alex', 'Finley']
    tasks = ['order batching', 'routing audit', 'line inspection', 'inventory sync']

    # Cost matrix (members × tasks)
    cost_matrix = [
        [28, 8, 24, 17],    # Bailey
        [25, 28, 12, 26],   # Casey
        [10, 16, 16, 13],   # Alex
        [14, 21, 8, 8]      # Finley
    ]

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], cost_matrix[i][j])
    objective.SetMinimization()

    # Step 5: Constraints
    # Each task must be assigned to exactly one member
    for j in range(len(tasks)):
        constraint = solver.Constraint(1, 1)
        for i in range(len(members)):
            constraint.SetCoefficient(x[i, j], 1)

    # Each member must be assigned to exactly one task
    for i in range(len(members)):
        constraint = solver.Constraint(1, 1)
        for j in range(len(tasks)):
            constraint.SetCoefficient(x[i, j], 1)

    # Step 6: Mathematical Model Summary
    # Minimize total assignment cost with assignment constraints

    # Step 7: Nonlinear Relationships
    # None - all relationships are linear

    # Step 8: Final Model and Implementation Considerations
    # Solve the MILP model
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    assignment[members[i]] = tasks[j]

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

