from ortools.linear_solver import pywraplp
import json

def solve_knapsack():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Item data
    values = [42, 14, 19, 37, 36, 31]
    weights = [10, 10, 3, 5, 9, 7]
    capacity = 26
    num_items = len(values)

    # Decision variables
    x = []
    for i in range(num_items):
        x.append(solver.BoolVar(f'x_{i}'))

    # Objective function: maximize total value
    objective = solver.Objective()
    for i in range(num_items):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Weight constraint
    solver.Add(sum(weights[i] * x[i] for i in range(num_items)) <= capacity)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_value = objective.Value()
        selected_items = [i for i in range(num_items) if x[i].solution_value() > 0.5]
    else:
        total_value = 0
        selected_items = []

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_knapsack()

