def solve_assignment_problem():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define members and tasks
    members = ['Finley', 'Bailey', 'Emery', 'Casey']
    tasks = ['line inspection', 'inventory sync', 'order batching', 'routing audit']

    # Cost matrix
    costs = {
        'Finley': {'line inspection': 24, 'inventory sync': 18, 'order batching': 18, 'routing audit': 16},
        'Bailey': {'line inspection': 13, 'inventory sync': 20, 'order batching': 9, 'routing audit': 24},
        'Emery': {'line inspection': 22, 'inventory sync': 11, 'order batching': 26, 'routing audit': 18},
        'Casey': {'line inspection': 10, 'inventory sync': 18, 'order batching': 15, 'routing audit': 25}
    }

    # Create decision variables
    x = {}
    for member in members:
        for task in tasks:
            x[(member, task)] = solver.BoolVar(f'x_{member}_{task}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for member in members:
        for task in tasks:
            objective.SetCoefficient(x[(member, task)], costs[member][task])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one member
    for task in tasks:
        constraint = solver.Constraint(1, 1)
        for member in members:
            constraint.SetCoefficient(x[(member, task)], 1)

    # Constraints: each member assigned to exactly one task
    for member in members:
        constraint = solver.Constraint(1, 1)
        for task in tasks:
            constraint.SetCoefficient(x[(member, task)], 1)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        print("Optimal assignment found:")
        for member in members:
            for task in tasks:
                if x[(member, task)].solution_value() > 0.5:
