def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['cooling_racks', 'battery_packs', 'power_modules', 'sensor_kits']

    # Parameters
    unit_profit = [24, 29, 29, 32]
    fixed_cost = [73, 96, 105, 109]
    labor_hours = [6, 2, 4, 3]
    max_production = [18, 19, 17, 18]
    total_labor = 126

    # Decision variables
    x = [solver.IntVar(0, max_production[i], f'x_{products[i]}') for i in range(len(products))]
    y = [solver.BoolVar(f'y_{products[i]}') for i in range(len(products))]

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(len(products)):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -fixed_cost[i])
    objective.SetMaximization()

    # Constraints
    # Labor constraint
    labor_constraint = solver.Constraint(0, total_labor)
    for i in range(len(products)):
        labor_constraint.SetCoefficient(x[i], labor_hours[i])

    # Production capacity constraints
    for i in range(len(products)):
        solver.Add(x[i] <= max_production[i])

    # Activation constraints
    for i in range(len(products)):
        solver.Add(x[i] <= max_production[i] * y[i])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        solution = {
            'status': 'OPTIMAL',
            'objective_value': solver.Objective().Value(),
            'production': {products[i]: x[i].solution_value() for i in range(len(products))},
            'activation': {products[i]: y[i].solution_value() for i in range(len(products))}
        }
    else:
        solution = {
            'status': 'INFEASIBLE',
            'objective_value': None,
            'production': None,
            'activation': None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

