import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Binary activation variables
    x_S = solver.BoolVar('x_S')  # sensor kits activation
    x_C = solver.BoolVar('x_C')  # control units activation
    x_B = solver.BoolVar('x_B')  # battery packs activation

    # Integer production quantity variables
    q_S = solver.IntVar(0, 8, 'q_S')  # sensor kits quantity
    q_C = solver.IntVar(0, 11, 'q_C')  # control units quantity
    q_B = solver.IntVar(0, 19, 'q_B')  # battery packs quantity

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(q_S, 36)
    objective.SetCoefficient(q_C, 26)
    objective.SetCoefficient(q_B, 27)
    objective.SetCoefficient(x_S, -110)
    objective.SetCoefficient(x_C, -55)
    objective.SetCoefficient(x_B, -48)
    objective.SetMaximization()

    # Constraints
    # Labor constraint
    solver.Add(6 * q_S + 4 * q_C + 2 * q_B <= 79)

    # Activation constraints
    solver.Add(q_S <= 8 * x_S)
    solver.Add(q_C <= 11 * x_C)
    solver.Add(q_B <= 19 * x_B)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        objective_value = objective.Value()
        result = {
            "status": "OPTIMAL",
            "objective_value": objective_value,
            "production": {
                "sensor_kits": int(q_S.solution_value()),
                "control_units": int(q_C.solution_value()),
                "battery_packs": int(q_B.solution_value())
            },
            "activation": {
                "sensor_kits": int(x_S.solution_value()),
                "control_units": int(x_C.solution_value()),
                "battery_packs": int(x_B.solution_value())
            }
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

