    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 12, 'x_S')  # sensor kits
    x_C = solver.IntVar(0, 11, 'x_C')  # control units
    x_B = solver.IntVar(0, 8, 'x_B')   # battery packs
    x_P = solver.IntVar(0, 18, 'x_P')  # power modules

    y_S = solver.BoolVar('y_S')  # sensor kits activation
    y_C = solver.BoolVar('y_C')  # control units activation
    y_B = solver.BoolVar('y_B')  # battery packs activation
    y_P = solver.BoolVar('y_P')  # power modules activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 26)
    objective.SetCoefficient(x_C, 31)
    objective.SetCoefficient(x_B, 26)
    objective.SetCoefficient(x_P, 20)
    objective.SetCoefficient(y_S, -58)
    objective.SetCoefficient(y_C, -80)
    objective.SetCoefficient(y_B, -74)
    objective.SetCoefficient(y_P, -63)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(3 * x_S + 3 * x_C + 2 * x_B + 2 * x_P <= 71)

