import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Binary activation variables
    x_B = solver.BoolVar('x_B')  # battery packs activation
    x_C = solver.BoolVar('x_C')  # cooling racks activation
    x_U = solver.BoolVar('x_U')  # control units activation
    x_P = solver.BoolVar('x_P')  # power modules activation

    # Integer production variables
    q_B = solver.IntVar(0, 13, 'q_B')  # battery packs quantity
    q_C = solver.IntVar(0, 17, 'q_C')  # cooling racks quantity
    q_U = solver.IntVar(0, 16, 'q_U')  # control units quantity
    q_P = solver.IntVar(0, 12, 'q_P')  # power modules quantity

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(q_B, 20)
    objective.SetCoefficient(q_C, 22)
    objective.SetCoefficient(q_U, 33)
    objective.SetCoefficient(q_P, 36)
    objective.SetCoefficient(x_B, -68)
    objective.SetCoefficient(x_C, -89)
    objective.SetCoefficient(x_U, -93)
    objective.SetCoefficient(x_P, -84)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(3 * q_B + 2 * q_C + 3 * q_U + 6 * q_P <= 92)

    # Activation constraints
    solver.Add(q_B <= 13 * x_B)
    solver.Add(q_C <= 17 * x_C)
    solver.Add(q_U <= 16 * x_U)
    solver.Add(q_P <= 12 * x_P)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "production": {
                "battery_packs": int(q_B.solution_value()),
                "cooling_racks": int(q_C.solution_value()),
                "control_units": int(q_U.solution_value()),
                "power_modules": int(q_P.solution_value())
            },
            "activation": {
                "battery_packs": int(x_B.solution_value()),
                "cooling_racks": int(x_C.solution_value()),
                "control_units": int(x_U.solution_value()),
                "power_modules": int(x_P.solution_value())
            }
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

