        'control_units': {'unit_profit': 34, 'fixed_cost': 60, 'labor_per_unit': 2, 'max_production': 8},
        'cooling_racks': {'unit_profit': 25, 'fixed_cost': 95, 'labor_per_unit': 5, 'max_production': 20}
    }

    # Step 2: Create solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Step 3: Define decision variables
    x = {}  # Production quantities (integer)
    y = {}  # Activation variables (binary)

    for p in products:
        x[p] = solver.IntVar(0, products[p]['max_production'], f'x_{p}')
        y[p] = solver.BoolVar(f'y_{p}')

    # Step 4: Define objective function
    objective = solver.Objective()
    for p in products:
        objective.SetCoefficient(x[p], products[p]['unit_profit'])
        objective.SetCoefficient(y[p], -products[p]['fixed_cost'])
    objective.SetMaximization()

    # Step 5: Add constraints
    # Labor constraint
    labor_constraint = solver.Constraint(0, 169)
    for p in products:
        labor_constraint.SetCoefficient(x[p], products[p]['labor_per_unit'])

    # Production limits and activation constraints
    for p in products:
        # Production limit
        solver.Add(x[p] <= products[p]['max_production'])
        # Activation constraint
        solver.Add(x[p] <= products[p]['max_production'] * y[p])

    # Step 6: Solve the problem
    status = solver.Solve()

