def solve_resource_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'PrimeSteel')
    x2 = solver.IntVar(0, solver.infinity(), 'SmartGlass')
    x3 = solver.IntVar(0, solver.infinity(), 'FlexCircuit')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 23)
    objective.SetCoefficient(x2, 48)
    objective.SetCoefficient(x3, 23)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint: 1x1 + 4x2 + 2x3 <= 37
    solver.Add(1 * x1 + 4 * x2 + 2 * x3 <= 37)

    # Raw material constraint: 1x1 + 4x2 + 1x3 <= 38
    solver.Add(1 * x1 + 4 * x2 + 1 * x3 <= 38)

    # Skilled labor constraint: 1x1 + 4x2 + 1x3 <= 33
    solver.Add(1 * x1 + 4 * x2 + 1 * x3 <= 33)

    # Solve the problem
    status = solver.Solve()

    # Check if the solution is optimal
    if status == pywraplp.Solver.OPTIMAL:
        print(f"Optimal solution found:")
