import json

def solve_knapsack():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Item data
    items = ['sensor pod', 'backup battery', 'edge server', 'relay box', 'portable scanner', 'field router']
    values = [45, 41, 38, 25, 12, 31]
    weights = [2, 3, 9, 2, 10, 4]
    capacity = 17

    # Decision variables
    x = []
    for i in range(len(items)):
        x.append(solver.BoolVar(f'x_{i}'))

    # Objective function: maximize total value
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Weight constraint
    constraint = solver.Constraint(0, capacity)
    for i in range(len(items)):
        constraint.SetCoefficient(x[i], weights[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    if status == pywraplp.Solver.OPTIMAL:
        selected_items = []
        total_value = 0
        total_weight = 0
        for i in range(len(items)):
            if x[i].solution_value() > 0.5:
                selected_items.append(items[i])
                total_value += values[i]
                total_weight += weights[i]

        result = {
            "status": "OPTIMAL",
            "objective_value": total_value,
            "selected_items": selected_items,
            "total_weight": total_weight
        }
    else:
        result = {
            "status": "NO_SOLUTION",
            "objective_value": 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

