def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 9, 'x_S')  # sensor kits quantity
    x_P = solver.IntVar(0, 14, 'x_P')  # power modules quantity
    x_C = solver.IntVar(0, 8, 'x_C')   # control units quantity

    y_S = solver.BoolVar('y_S')  # sensor kits activation
    y_P = solver.BoolVar('y_P')  # power modules activation
    y_C = solver.BoolVar('y_C')  # control units activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 24)
    objective.SetCoefficient(x_P, 18)
    objective.SetCoefficient(x_C, 32)
    objective.SetCoefficient(y_S, -53)
    objective.SetCoefficient(y_P, -69)
    objective.SetCoefficient(y_C, -46)
    objective.SetMaximization()

    # Constraints
    # Total working hours constraint
    solver.Add(6 * x_S + 6 * x_P + 5 * x_C <= 124)

    # Activation constraints
    solver.Add(x_S <= 9 * y_S)
    solver.Add(x_P <= 14 * y_P)
    solver.Add(x_C <= 8 * y_C)

