def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Binary activation variables
    x_CR = solver.BoolVar('x_CR')
    x_BP = solver.BoolVar('x_BP')
    x_SK = solver.BoolVar('x_SK')

    # Integer production quantity variables
    q_CR = solver.IntVar(0, 8, 'q_CR')
    q_BP = solver.IntVar(0, 14, 'q_BP')
    q_SK = solver.IntVar(0, 17, 'q_SK')

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(q_CR, 30)
    objective.SetCoefficient(q_BP, 34)
    objective.SetCoefficient(q_SK, 34)
    objective.SetCoefficient(x_CR, -85)
    objective.SetCoefficient(x_BP, -70)
    objective.SetCoefficient(x_SK, -60)
    objective.SetMaximization()

    # Constraints
    # Total working hours constraint
    solver.Add(4 * q_CR + 2 * q_BP + 2 * q_SK <= 44)

    # Production quantity constraints with activation variables
    solver.Add(q_CR <= 8 * x_CR)
    solver.Add(q_BP <= 14 * x_BP)
    solver.Add(q_SK <= 17 * x_SK)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "production": {
                "cooling_racks": q_CR.solution_value(),
                "battery_packs": q_BP.solution_value(),
                "sensor_kits": q_SK.solution_value()
            },
            "activation": {
