def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 20, 'x1')  # Power modules quantity
    x2 = solver.IntVar(0, 11, 'x2')  # Control units quantity
    x3 = solver.IntVar(0, 9, 'x3')   # Sensor kits quantity

    y1 = solver.BoolVar('y1')  # Power modules activation
    y2 = solver.BoolVar('y2')  # Control units activation
    y3 = solver.BoolVar('y3')  # Sensor kits activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 30)
    objective.SetCoefficient(x2, 31)
    objective.SetCoefficient(x3, 18)
    objective.SetCoefficient(y1, -51)
    objective.SetCoefficient(y2, -73)
    objective.SetCoefficient(y3, -97)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(2 * x1 + 3 * x2 + 4 * x3 <= 68)

    # Production capacity constraints
    solver.Add(x1 <= 20)
    solver.Add(x2 <= 11)
    solver.Add(x3 <= 9)

    # Activation constraints
    solver.Add(x1 <= 20 * y1)
    solver.Add(x2 <= 11 * y2)
