import json

def solve_production_problem():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, solver.infinity(), 'FlexCircuit')
    x2 = solver.IntVar(0, solver.infinity(), 'BioResin')
    x3 = solver.IntVar(0, solver.infinity(), 'AeroFoam')

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 44)
    objective.SetCoefficient(x2, 26)
    objective.SetCoefficient(x3, 21)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint: 2x1 + 5x2 + x3 <= 36
    machine_hours = solver.Constraint(0, 36)
    machine_hours.SetCoefficient(x1, 2)
    machine_hours.SetCoefficient(x2, 5)
    machine_hours.SetCoefficient(x3, 1)

    # Raw material constraint: 2x1 + 6x2 + x3 <= 53
    raw_material = solver.Constraint(0, 53)
    raw_material.SetCoefficient(x1, 2)
    raw_material.SetCoefficient(x2, 6)
    raw_material.SetCoefficient(x3, 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        flex_circuit = x1.solution_value()
        bio_resin = x2.solution_value()
        aero_foam = x3.solution_value()
        total_profit = objective.Value()

        print(f"Optimal production plan:")
        print(f"FlexCircuit: {flex_circuit} units")
        print(f"BioResin: {bio_resin} units")
        print(f"AeroFoam: {aero_foam} units")
        print(f"Total profit: {total_profit}")

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

