    objective.SetCoefficient(x_prime, 31)
    objective.SetCoefficient(x_smart, 42)
    objective.SetCoefficient(x_bio, 18)
    objective.SetMaximization()

    # Add constraints
    # Machine hours constraint
    solver.Add(6 * x_aero + 6 * x_prime + 1 * x_smart + 3 * x_bio <= 81)

    # Raw material constraint
    solver.Add(4 * x_aero + 3 * x_prime + 1 * x_smart + 4 * x_bio <= 68)

