import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Production quantities (integer)
    x_power = solver.IntVar(0, 12, 'x_power')
    x_control = solver.IntVar(0, 14, 'x_control')
    x_cooling = solver.IntVar(0, 16, 'x_cooling')

    # Activation variables (binary)
    y_power = solver.BoolVar('y_power')
    y_control = solver.BoolVar('y_control')
    y_cooling = solver.BoolVar('y_cooling')

    # Objective: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x_power, 24)
    objective.SetCoefficient(x_control, 31)
    objective.SetCoefficient(x_cooling, 32)
    objective.SetCoefficient(y_power, -110)
    objective.SetCoefficient(y_control, -86)
    objective.SetCoefficient(y_cooling, -61)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(5 * x_power + 5 * x_control + 4 * x_cooling <= 96)

    # Activation constraints
    solver.Add(x_power <= 12 * y_power)
    solver.Add(x_control <= 14 * y_control)
    solver.Add(x_cooling <= 16 * y_cooling)

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": solver.Objective().Value(),
        "production": {
            "power_modules": int(x_power.solution_value()),
            "control_units": int(x_control.solution_value()),
            "cooling_racks": int(x_cooling.solution_value())
        },
        "activation": {
            "power_modules": int(y_power.solution_value()),
            "control_units": int(y_control.solution_value()),
            "cooling_racks": int(y_cooling.solution_value())
        }
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

