from ortools.linear_solver import pywraplp
import json

def main():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_flex = solver.NumVar(0, solver.infinity(), 'x_flex')
    x_bio = solver.NumVar(0, solver.infinity(), 'x_bio')
    x_eco = solver.NumVar(0, solver.infinity(), 'x_eco')
    x_aero = solver.NumVar(0, solver.infinity(), 'x_aero')

    # Objective function: maximize total profit
    solver.Maximize(22 * x_flex + 21 * x_bio + 31 * x_eco + 24 * x_aero)

    # Constraints
    # Machine hours constraint
    solver.Add(4 * x_flex + 6 * x_bio + 5 * x_eco + 1 * x_aero <= 74)

    # Raw material constraint
    solver.Add(1 * x_flex + 6 * x_bio + 6 * x_eco + 5 * x_aero <= 95)

    # Solve the problem
    status = solver.Solve()

    # Print the results
    if status == pywraplp.Solver.OPTIMAL:
        print("Optimal solution found:")
        print(f"FlexCircuit: {x_flex.solution_value()}")
        print(f"BioResin: {x_bio.solution_value()}")
        print(f"EcoFuel: {x_eco.solution_value()}")
        print(f"AeroFoam: {x_aero.solution_value()}")
        print(f"Total profit: {solver.Objective().Value()}")
    else:
        print("No optimal solution found")

    # Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

