from ortools.linear_solver import pywraplp
import json

def solve_knapsack():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Item data: [value, weight]
    items = [
        [32, 6],   # sensor pod
        [18, 5],   # field router
        [12, 10],  # relay box
        [15, 6],   # edge server
        [25, 10],  # backup battery
        [25, 2]    # thermal camera
    ]
    num_items = len(items)
    capacity = 20

    # Decision variables
    x = []
    for i in range(num_items):
        x.append(solver.BoolVar(f'x_{i}'))

    # Objective function: maximize total value
    objective = solver.Objective()
    for i in range(num_items):
        objective.SetCoefficient(x[i], items[i][0])
    objective.SetMaximization()

    # Weight constraint
    weight_constraint = solver.Constraint(0, capacity)
    for i in range(num_items):
        weight_constraint.SetCoefficient(x[i], items[i][1])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    total_value = 0
    total_weight = 0
    selected_items = []

    for i in range(num_items):
        if x[i].solution_value() > 0.5:
            total_value += items[i][0]
            total_weight += items[i][1]
            selected_items.append(i)

    # Print result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_knapsack()

