from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['battery packs', 'cooling racks', 'sensor kits', 'power modules']
    num_products = len(products)

    # Parameters
    unit_profit = [30, 20, 33, 26]
    setup_cost = [51, 72, 83, 107]
    unit_time = [4, 2, 3, 5]
    capacity = [20, 13, 11, 19]
    total_time = 135

    # Decision variables
    x = []  # Production quantities
    y = []  # Activation variables

    for i in range(num_products):
        # Integer variables for production quantities
        x_i = solver.IntVar(0, capacity[i], f'x_{i}')
        x.append(x_i)

        # Binary variables for activation
        y_i = solver.BoolVar(f'y_{i}')
        y.append(y_i)

    # Objective function: maximize net profit
    objective = solver.Objective()
    for i in range(num_products):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -setup_cost[i])
    objective.SetMaximization()

    # Constraints
    # 1. Total time constraint
    time_constraint = solver.Constraint(0, total_time)
    for i in range(num_products):
        time_constraint.SetCoefficient(x[i], unit_time[i])

    # 2. Linking constraints: x_i <= capacity[i] * y_i
    for i in range(num_products):
        linking_constraint = solver.Constraint(-solver.infinity(), 0)
        linking_constraint.SetCoefficient(x[i], 1)
        linking_constraint.SetCoefficient(y[i], -capacity[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value(),
        'production_quantities': [x[i].solution_value() for i in range(num_products)],
        'activation': [y[i].solution_value() for i in range(num_products)]
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_production_planning()

