import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_S = solver.IntVar(0, 12, 'x_S')  # sensor kits quantity
    x_P = solver.IntVar(0, 12, 'x_P')  # power modules quantity
    x_B = solver.IntVar(0, 18, 'x_B')  # battery packs quantity

    y_S = solver.BoolVar('y_S')  # sensor kits activation
    y_P = solver.BoolVar('y_P')  # power modules activation
    y_B = solver.BoolVar('y_B')  # battery packs activation

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetCoefficient(x_S, 22)
    objective.SetCoefficient(x_P, 18)
    objective.SetCoefficient(x_B, 26)
    objective.SetCoefficient(y_S, -46)
    objective.SetCoefficient(y_P, -55)
    objective.SetCoefficient(y_B, -68)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(2 * x_S + 5 * x_P + 4 * x_B <= 102)

    # Production limits
    solver.Add(x_S <= 12)
    solver.Add(x_P <= 12)
    solver.Add(x_B <= 18)

    # Activation constraints
    solver.Add(x_S <= 12 * y_S)
    solver.Add(x_P <= 12 * y_P)
    solver.Add(x_B <= 18 * y_B)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x_S": x_S.solution_value(),
            "x_P": x_P.solution_value(),
            "x_B": x_B.solution_value(),
            "y_S": y_S.solution_value(),
            "y_P": y_P.solution_value(),
            "y_B": y_B.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

