    members = ['Bailey', 'Casey', 'Drew', 'Alex']
    tasks = ['routing audit', 'order batching', 'inventory sync', 'line inspection']

    # Cost matrix
    costs = {
        'Bailey': {'routing audit': 13, 'order batching': 27, 'inventory sync': 28, 'line inspection': 16},
        'Casey': {'routing audit': 27, 'order batching': 23, 'inventory sync': 9, 'line inspection': 25},
