def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['battery_packs', 'power_modules', 'control_units', 'cooling_racks']

    # Parameters
    unit_profit = {'battery_packs': 19, 'power_modules': 21, 'control_units': 36, 'cooling_racks': 25}
    setup_cost = {'battery_packs': 105, 'power_modules': 91, 'control_units': 66, 'cooling_racks': 102}
    labor_time = {'battery_packs': 3, 'power_modules': 5, 'control_units': 3, 'cooling_racks': 6}
    max_production = {'battery_packs': 9, 'power_modules': 20, 'control_units': 13, 'cooling_racks': 18}
    total_labor = 160

    # Decision variables
    x = {}
    y = {}
    for product in products:
        x[product] = solver.IntVar(0, max_production[product], f'x_{product}')
        y[product] = solver.BoolVar(f'y_{product}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for product in products:
        objective.SetCoefficient(x[product], unit_profit[product])
        objective.SetCoefficient(y[product], -setup_cost[product])
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    labor_constraint = solver.Constraint(0, total_labor)
    for product in products:
        labor_constraint.SetCoefficient(x[product], labor_time[product])

    # Setup activation constraints
    for product in products:
        setup_constraint = solver.Constraint(-solver.infinity(), 0)
        setup_constraint.SetCoefficient(x[product], 1)
        setup_constraint.SetCoefficient(y[product], -max_production[product])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_profit = objective.Value()
        result = {
            'status': 'OPTIMAL',
            'objective_value': total_profit,
            'production': {product: x[product].solution_value() for product in products},
            'setup': {product: y[product].solution_value() for product in products}
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': 0,
            'production': {product: 0 for product in products},
            'setup': {product: 0 for product in products}
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

