from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_p = solver.IntVar(0, 17, 'x_p')  # Power modules quantity
    x_s = solver.IntVar(0, 12, 'x_s')  # Sensor kits quantity
    x_b = solver.IntVar(0, 20, 'x_b')  # Battery packs quantity
    y_p = solver.BoolVar('y_p')  # Power modules activation
    y_s = solver.BoolVar('y_s')  # Sensor kits activation
    y_b = solver.BoolVar('y_b')  # Battery packs activation

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x_p, 31)
    objective.SetCoefficient(x_s, 19)
    objective.SetCoefficient(x_b, 28)
    objective.SetCoefficient(y_p, -76)
    objective.SetCoefficient(y_s, -105)
    objective.SetCoefficient(y_b, -89)
    objective.SetMaximization()

    # Constraints
    # Total working hours constraint
    solver.Add(5 * x_p + 6 * x_s + 5 * x_b <= 170)

    # Production quantity constraints with activation variables
    solver.Add(x_p <= 17 * y_p)
    solver.Add(x_s <= 12 * y_s)
    solver.Add(x_b <= 20 * y_b)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        result = {
            "status": "OPTIMAL",
            "objective_value": objective.Value(),
            "x_p": x_p.solution_value(),
            "x_s": x_s.solution_value(),
            "x_b": x_b.solution_value(),
            "y_p": y_p.solution_value(),
            "y_s": y_s.solution_value(),
            "y_b": y_b.solution_value()
        }
    else:
        result = {
            "status": "INFEASIBLE",
            "objective_value": 0.0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

