def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.IntVar(0, 12, 'x1')  # cooling racks
    x2 = solver.IntVar(0, 13, 'x2')  # battery packs
    x3 = solver.IntVar(0, 12, 'x3')  # control units

    y1 = solver.BoolVar('y1')  # setup for cooling racks
    y2 = solver.BoolVar('y2')  # setup for battery packs
    y3 = solver.BoolVar('y3')  # setup for control units

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 33)
    objective.SetCoefficient(x2, 19)
    objective.SetCoefficient(x3, 26)
    objective.SetCoefficient(y1, -72)
    objective.SetCoefficient(y2, -75)
    objective.SetCoefficient(y3, -88)
    objective.SetMaximization()

    # Constraints
    # Labor time constraint
    solver.Add(4 * x1 + 5 * x2 + 4 * x3 <= 89)

    # Setup activation constraints
    solver.Add(x1 <= 12 * y1)
    solver.Add(x2 <= 13 * y2)
