import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products and their parameters
    products = {
        'sensor_kits': {'c': 36, 'f': 106, 't': 5, 'max_q': 15},
        'control_units': {'c': 30, 'f': 80, 't': 2, 'max_q': 12},
        'power_modules': {'c': 18, 'f': 59, 't': 3, 'max_q': 19},
        'battery_packs': {'c': 31, 'f': 97, 't': 4, 'max_q': 14}
    }

    # Decision variables
    x = {}  # Production quantities
    y = {}  # Activation variables

    for p, params in products.items():
        x[p] = solver.IntVar(0, params['max_q'], f'x_{p}')
        y[p] = solver.BoolVar(f'y_{p}')

    # Objective function: maximize total profit
    objective = solver.Objective()
    for p, params in products.items():
        objective.SetCoefficient(x[p], params['c'])
        objective.SetCoefficient(y[p], -params['f'])
    objective.SetMaximization()

    # Labor time constraint
    labor_constraint = solver.Constraint(0, 98)
    for p, params in products.items():
        labor_constraint.SetCoefficient(x[p], params['t'])

    # Production activation constraints
    for p, params in products.items():
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(x[p], 1)
        activation_constraint.SetCoefficient(y[p], -params['max_q'])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value()
    }

