from ortools.linear_solver import pywraplp
import json

def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Parameters
    products = ['control units', 'cooling racks', 'sensor kits', 'power modules']
    p = [20, 27, 26, 29]  # unit contribution profit
    f = [47, 73, 68, 99]  # fixed setup cost
    t = [3, 4, 6, 6]      # labor time per unit
    M = [19, 11, 17, 17]  # maximum production quantity
    T = 166               # total available labor time

    # Decision variables
    x = []  # production quantities
    y = []  # binary activation variables

    for i in range(len(products)):
        x.append(solver.IntVar(0, M[i], f'x_{i}'))
        y.append(solver.BoolVar(f'y_{i}'))

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(len(products)):
        objective.SetCoefficient(x[i], p[i])
        objective.SetCoefficient(y[i], -f[i])
    objective.SetMaximization()

    # Constraints
    # 1. Total labor time constraint
    labor_constraint = solver.Constraint(0, T)
    for i in range(len(products)):
        labor_constraint.SetCoefficient(x[i], t[i])

    # 2. Setup activation constraints
    for i in range(len(products)):
        setup_constraint = solver.Constraint(-solver.infinity(), 0)
        setup_constraint.SetCoefficient(x[i], 1)
        setup_constraint.SetCoefficient(y[i], -M[i])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value(),
        "production_plan": []
    }

    for i in range(len(products)):
        result["production_plan"].append({
            "product": products[i],
            "quantity": x[i].solution_value(),
            "produced": y[i].solution_value() > 0.5
        })

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

