def solve_production_planning():
    # Initialize the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['power_modules', 'battery_packs', 'sensor_kits']
    num_products = len(products)

    # Parameters
    unit_profit = [22, 20, 36]
    fixed_cost = [90, 85, 87]
    unit_time = [4, 5, 3]
    max_production = [18, 19, 13]
    total_time_limit = 125

    # Decision variables
    x = []  # Binary activation variables
    y = []  # Integer production variables

    for i in range(num_products):
        x.append(solver.BoolVar(f'x_{products[i]}'))
        y.append(solver.IntVar(0, max_production[i], f'y_{products[i]}'))

    # Objective function: maximize total profit
    objective = solver.Objective()
    for i in range(num_products):
        objective.SetCoefficient(y[i], unit_profit[i])
        objective.SetCoefficient(x[i], -fixed_cost[i])
    objective.SetMaximization()

    # Constraints
    # 1. Total labor time constraint
    time_constraint = solver.Constraint(0, total_time_limit)
    for i in range(num_products):
        time_constraint.SetCoefficient(y[i], unit_time[i])

    # 2. Production limits (already handled in variable definition)

    # 3. Activation constraints
    for i in range(num_products):
        activation_constraint = solver.Constraint(-solver.infinity(), 0)
        activation_constraint.SetCoefficient(y[i], 1)
        activation_constraint.SetCoefficient(x[i], -max_production[i])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_profit = objective.Value()
        result = {
            'status': 'OPTIMAL',
            'objective_value': total_profit,
            'production': {
                products[i]: int(y[i].solution_value()) for i in range(num_products)
            },
            'activation': {
                products[i]: int(x[i].solution_value()) for i in range(num_products)
            }
        }
    else:
        result = {
            'status': 'INFEASIBLE',
            'objective_value': 0
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

