def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_B = solver.IntVar(0, 17, 'x_B')  # battery packs
    x_C = solver.IntVar(0, 11, 'x_C')  # control units
    x_P = solver.IntVar(0, 17, 'x_P')  # power modules
    x_S = solver.IntVar(0, 15, 'x_S')  # sensor kits

    y_B = solver.BoolVar('y_B')  # battery packs activation
    y_C = solver.BoolVar('y_C')  # control units activation
    y_P = solver.BoolVar('y_P')  # power modules activation
    y_S = solver.BoolVar('y_S')  # sensor kits activation

    # Objective function: maximize net profit
    objective = solver.Objective()
    objective.SetCoefficient(x_B, 23)
    objective.SetCoefficient(x_C, 18)
    objective.SetCoefficient(x_P, 33)
    objective.SetCoefficient(x_S, 22)
    objective.SetCoefficient(y_B, -91)
    objective.SetCoefficient(y_C, -59)
    objective.SetCoefficient(y_P, -78)
    objective.SetCoefficient(y_S, -73)
    objective.SetMaximization()

    # Constraints
    # Labor hour constraint
    solver.Add(3 * x_B + 6 * x_C + 4 * x_P + 4 * x_S <= 163)

    # Production activation constraints
    solver.Add(x_B <= 17 * y_B)
    solver.Add(x_C <= 11 * y_C)
    solver.Add(x_P <= 17 * y_P)
    solver.Add(x_S <= 15 * y_S)

    # Solve the problem
    status = solver.Solve()

    # Prepare the result
    result = {
        "status": "OPTIMAL" if status == pywraplp.Solver.OPTIMAL else "NOT_OPTIMAL",
        "objective_value": objective.Value()
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

