from ortools.linear_solver import pywraplp
import json

def main():
    # Step 1: Define the cost matrix
    members = ['Alex', 'Drew', 'Finley', 'Casey']
    tasks = ['order batching', 'inventory sync', 'routing audit', 'line inspection']

    # Cost matrix: rows are members, columns are tasks
    cost_matrix = [
        [26, 16, 19, 10],  # Alex
        [16, 23, 8, 12],   # Drew
        [16, 13, 16, 15],  # Finley
        [23, 23, 22, 17]   # Casey
    ]

    # Step 2: Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Step 3: Define decision variables
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Step 4: Set up the objective function
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], cost_matrix[i][j])
    objective.SetMinimization()

    # Step 5: Add constraints
    # Each task must be assigned to exactly one member
    for j in range(len(tasks)):
        constraint = solver.Constraint(1, 1)
        for i in range(len(members)):
            constraint.SetCoefficient(x[i, j], 1)

    # Each member must be assigned exactly one task
    for i in range(len(members)):
        constraint = solver.Constraint(1, 1)
        for j in range(len(tasks)):
            constraint.SetCoefficient(x[i, j], 1)

    # Step 6: Solve the problem
    status = solver.Solve()

    # Step 7: Print results
    if status == solver.OPTIMAL:
        print("Optimal assignment found:")
        total_cost = 0
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    print(f"{members[i]} assigned to {tasks[j]} with cost {cost_matrix[i][j]}")
                    total_cost += cost_matrix[i][j]
        print(f"Total cost: {total_cost}")
    else:
        print("No optimal solution found")

    # Step 8: Print the result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    main()

