import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = {
        'cooling_racks': {'profit': 23, 'cost': 55, 'hours': 4, 'max': 17},
        'battery_packs': {'profit': 29, 'cost': 92, 'hours': 3, 'max': 20},
        'sensor_kits': {'profit': 36, 'cost': 63, 'hours': 2, 'max': 16},
        'power_modules': {'profit': 23, 'cost': 78, 'hours': 4, 'max': 17}
    }

    # Decision variables
    x = {}
    y = {}
    for p, data in products.items():
        x[p] = solver.IntVar(0, data['max'], f'x_{p}')
        y[p] = solver.BoolVar(f'y_{p}')

    # Objective function: maximize profit
    objective = solver.Objective()
    for p, data in products.items():
        objective.SetCoefficient(x[p], data['profit'])
        objective.SetCoefficient(y[p], -data['cost'])
    objective.SetMaximization()

    # Constraints
    # 1. Labor hour constraint
    labor_constraint = solver.Constraint(0, 113)
    for p, data in products.items():
        labor_constraint.SetCoefficient(x[p], data['hours'])

    # 2. Production limits and setup activation
    for p, data in products.items():
        # Production limit
        solver.Add(x[p] <= data['max'])
        # Setup activation: if x_p > 0, then y_p must be 1
        solver.Add(x[p] <= data['max'] * y[p])

    # Solve the problem
    status = solver.Solve()

    # Prepare results
    result = {
        'status': 'OPTIMAL' if status == pywraplp.Solver.OPTIMAL else 'NOT_OPTIMAL',
        'objective_value': solver.Objective().Value(),
        'production': {p: x[p].solution_value() for p in products},
        'setup': {p: y[p].solution_value() for p in products}
    }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

