import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define products
    products = ['sensor_kits', 'battery_packs', 'control_units', 'cooling_racks']
    num_products = len(products)

    # Parameters
    unit_profit = [26, 32, 24, 27]
    fixed_cost = [83, 67, 74, 56]
    unit_time = [2, 3, 5, 2]
    max_quantity = [17, 17, 9, 13]
    total_time = 76

    # Decision variables
    x = []  # Production quantities
    y = []  # Activation variables

    for i in range(num_products):
        # Integer variables for production quantities
        x_i = solver.IntVar(0, max_quantity[i], f'x_{i}')
        x.append(x_i)

        # Binary variables for activation
        y_i = solver.BoolVar(f'y_{i}')
        y.append(y_i)

    # Objective: maximize total profit
    objective = solver.Objective()
    for i in range(num_products):
        objective.SetCoefficient(x[i], unit_profit[i])
        objective.SetCoefficient(y[i], -fixed_cost[i])
    objective.SetMaximization()

    # Constraints
    # 1. Total time constraint
    time_constraint = solver.Constraint(0, total_time)
    for i in range(num_products):
        time_constraint.SetCoefficient(x[i], unit_time[i])

    # 2. Production quantity constraints
    for i in range(num_products):
        # If y_i = 0, then x_i must be 0
        # If y_i = 1, then x_i can be up to max_quantity[i]
        solver.Add(x[i] <= max_quantity[i] * y[i])

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        production_plan = []
        total_profit = 0
        for i in range(num_products):
            quantity = x[i].solution_value()
            activated = y[i].solution_value()
            if activated > 0.5:
                profit = unit_profit[i] * quantity - fixed_cost[i]
                total_profit += profit
                production_plan.append({
                    'product': products[i],
                    'quantity': int(quantity),
                    'activated': True
                })
            else:
                production_plan.append({
                    'product': products[i],
                    'quantity': 0,
                    'activated': False
                })

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_production_planning()

