def solve_resource_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x1 = solver.NumVar(0, solver.infinity(), 'x1')  # AeroFoam
    x2 = solver.NumVar(0, solver.infinity(), 'x2')  # SmartGlass
    x3 = solver.NumVar(0, solver.infinity(), 'x3')  # PrimeSteel
    x4 = solver.NumVar(0, solver.infinity(), 'x4')  # EcoFuel

    # Objective function: maximize total profit
    objective = solver.Objective()
    objective.SetCoefficient(x1, 24)
    objective.SetCoefficient(x2, 19)
    objective.SetCoefficient(x3, 31)
    objective.SetCoefficient(x4, 43)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint: 4*x1 + 1*x2 + 4*x3 + 3*x4 ≤ 62
    machine_hours = solver.Constraint(0, 62)
    machine_hours.SetCoefficient(x1, 4)
    machine_hours.SetCoefficient(x2, 1)
    machine_hours.SetCoefficient(x3, 4)
    machine_hours.SetCoefficient(x4, 3)

    # Raw material constraint: 6*x1 + 4*x2 + 1*x3 + 4*x4 ≤ 71
    raw_material = solver.Constraint(0, 71)
    raw_material.SetCoefficient(x1, 6)
    raw_material.SetCoefficient(x2, 4)
    raw_material.SetCoefficient(x3, 1)
    raw_material.SetCoefficient(x4, 4)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        optimal_value = objective.Value()
        result = {
            "status": "OPTIMAL",
            "objective_value": optimal_value,
            "x1": x1.solution_value(),
            "x2": x2.solution_value(),
            "x3": x3.solution_value(),
            "x4": x4.solution_value()
        }
    else:
        result = {
            "status": "NOT_OPTIMAL",
            "objective_value": None
        }

    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

