def solve_knapsack():
    # 创建求解器
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # 设备名称、价值和重量
    items = ['edge server', 'sensor pod', 'portable scanner', 'field router', 'thermal camera', 'backup battery']
    values = [31, 23, 20, 34, 14, 45]
    weights = [10, 9, 9, 4, 9, 10]
    capacity = 21

    # 创建决策变量
    x = []
    for i in range(len(items)):
        x.append(solver.BoolVar(f'x_{i}'))

    # 设置目标函数：最大化总价值
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
