import json

def solve_production_planning():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    # Binary activation variables
    x_B = solver.BoolVar('x_B')  # battery packs
    x_C = solver.BoolVar('x_C')  # control units
    x_S = solver.BoolVar('x_S')  # sensor kits
    x_P = solver.BoolVar('x_P')  # power modules

    # Integer production variables
    q_B = solver.IntVar(0, 16, 'q_B')  # battery packs
    q_C = solver.IntVar(0, 10, 'q_C')  # control units
    q_S = solver.IntVar(0, 20, 'q_S')  # sensor kits
    q_P = solver.IntVar(0, 19, 'q_P')  # power modules

    # Objective function: maximize profit
    objective = solver.Objective()
    objective.SetMaximization()
    objective.SetCoefficient(q_B, 28)
    objective.SetCoefficient(q_C, 29)
    objective.SetCoefficient(q_S, 18)
    objective.SetCoefficient(q_P, 35)
    objective.SetCoefficient(x_B, -69)
    objective.SetCoefficient(x_C, -109)
    objective.SetCoefficient(x_S, -83)
    objective.SetCoefficient(x_P, -93)

    # Constraints
    # Labor time constraint
    solver.Add(5 * q_B + 6 * q_C + 2 * q_S + 4 * q_P <= 146)

    # Production activation constraints
    solver.Add(q_B <= 16 * x_B)
    solver.Add(q_C <= 10 * x_C)
    solver.Add(q_S <= 20 * x_S)
    solver.Add(q_P <= 19 * x_P)

    # Solve the problem
    status = solver.Solve()

    # Output results
    if status == pywraplp.Solver.OPTIMAL:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

