def solve_resource_allocation():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Decision variables
    x_aero = solver.IntVar(0, solver.infinity(), 'x_aero')
    x_bio = solver.IntVar(0, solver.infinity(), 'x_bio')
    x_prime = solver.IntVar(0, solver.infinity(), 'x_prime')
    x_eco = solver.IntVar(0, solver.infinity(), 'x_eco')
    x_smart = solver.IntVar(0, solver.infinity(), 'x_smart')

    # Objective function: maximize total profit
    solver.Maximize(37 * x_aero + 44 * x_bio + 44 * x_prime + 25 * x_eco + 38 * x_smart)

    # Constraints
    # Machine hours constraint
    solver.Add(3 * x_aero + 5 * x_bio + 5 * x_prime + 2 * x_eco + 4 * x_smart <= 110)

    # Raw material constraint
    solver.Add(4 * x_aero + 1 * x_bio + 5 * x_prime + 1 * x_eco + 5 * x_smart <= 85)

    # Solve the problem
    status = solver.Solve()

    # Print results
    if status == pywraplp.Solver.OPTIMAL:
        print("Optimal solution found:")
        print(f"AeroFoam: {x_aero.solution_value()}")
        print(f"BioResin: {x_bio.solution_value()}")
        print(f"PrimeSteel: {x_prime.solution_value()}")
        print(f"EcoFuel: {x_eco.solution_value()}")
        print(f"SmartGlass: {x_smart.solution_value()}")
        print(f"Total profit: {solver.Objective().Value()}")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("No optimal solution found")
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_resource_allocation()

