from ortools.linear_solver import pywraplp
import json

def solve_assignment_problem():
    # Create the solver
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # Define members and tasks
    members = ['Finley', 'Emery', 'Alex', 'Casey']
    tasks = ['order batching', 'inventory sync', 'line inspection', 'routing audit']

    # Cost matrix
    costs = [
        [19, 24, 9, 18],    # Finley
        [21, 9, 11, 10],    # Emery
        [25, 8, 13, 22],    # Alex
        [16, 12, 27, 11]    # Casey
    ]

    # Create decision variables
    x = {}
    for i in range(len(members)):
        for j in range(len(tasks)):
            x[i, j] = solver.IntVar(0, 1, f'x_{i}_{j}')

    # Objective function: minimize total cost
    objective = solver.Objective()
    for i in range(len(members)):
        for j in range(len(tasks)):
            objective.SetCoefficient(x[i, j], costs[i][j])
    objective.SetMinimization()

    # Constraints: each task assigned to exactly one member
    for j in range(len(tasks)):
        solver.Add(sum(x[i, j] for i in range(len(members))) == 1)

    # Constraints: each member assigned to exactly one task
    for i in range(len(members)):
        solver.Add(sum(x[i, j] for j in range(len(tasks))) == 1)

    # Solve the problem
    status = solver.Solve()

    # Extract results
    if status == pywraplp.Solver.OPTIMAL:
        total_cost = objective.Value()
        assignment = {}
        for i in range(len(members)):
            for j in range(len(tasks)):
                if x[i, j].solution_value() > 0.5:
                    assignment[members[i]] = tasks[j]
        print("Optimal assignment found:")
        for member, task in assignment.items():
            print(f"{member} -> {task}")
        print(f"Total cost: {total_cost}")
    else:
        print("No optimal solution found")

    # Print result marker
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_assignment_problem()

