import json

def solve_knapsack():
    # Step 1: Problem Description
    # We need to select items to maximize value without exceeding weight capacity of 19

    # Step 2: Sets and Parameters
    items = ['backup battery', 'sensor pod', 'relay box', 'thermal camera', 'portable scanner', 'field router']
    values = [33, 32, 43, 17, 43, 39]
    weights = [4, 8, 9, 6, 6, 8]
    capacity = 19

    # Step 3: Decision Variables
    solver = pywraplp.Solver.CreateSolver('SCIP')
    x = [solver.BoolVar(f'x_{i}') for i in range(len(items))]

    # Step 4: Objective Function
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # Step 5: Constraints
    weight_constraint = solver.Constraint(0, capacity)
    for i in range(len(items)):
        weight_constraint.SetCoefficient(x[i], weights[i])

    # Step 6: Solve the problem
    status = solver.Solve()

    # Step 7: Extract results
    selected_items = []
    total_value = 0
    total_weight = 0

    for i in range(len(items)):
        if x[i].solution_value() > 0.5:
            selected_items.append(items[i])
            total_value += values[i]
            total_weight += weights[i]

    # Step 8: Output results
    print("Selected items:", selected_items)
    print("Total value:", total_value)
    print("Total weight:", total_weight)

    # Return the result in the required format
    print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

if __name__ == '__main__':
    solve_knapsack()

