    objective = solver.Objective()
    objective.SetCoefficient(x_B, 48)
    objective.SetCoefficient(x_S, 43)
    objective.SetCoefficient(x_A, 45)
    objective.SetMaximization()

    # Constraints
    # Machine hours constraint
    solver.Add(4 * x_B + 5 * x_S + 2 * x_A <= 56)

    # Raw material constraint
    solver.Add(3 * x_B + 3 * x_S + 6 * x_A <= 69)

    # Solve the problem
    status = solver.Solve()

