from ortools.linear_solver import pywraplp
import json

def solve_knapsack():
    # 创建求解器
    solver = pywraplp.Solver.CreateSolver('SCIP')

    # 设备信息
    items = ['thermal camera', 'field router', 'relay box', 'portable scanner', 'backup battery']
    weights = [7, 7, 3, 2, 7]
    values = [32, 42, 43, 37, 43]
    capacity = 11

    # 创建决策变量
    x = []
    for i in range(len(items)):
        x.append(solver.BoolVar(f'x_{i}'))

    # 设置目标函数：最大化总价值
    objective = solver.Objective()
    for i in range(len(items)):
        objective.SetCoefficient(x[i], values[i])
    objective.SetMaximization()

    # 添加重量约束
    constraint = solver.Constraint(0, capacity)
    for i in range(len(items)):
        constraint.SetCoefficient(x[i], weights[i])

    # 求解
    status = solver.Solve()

    # 输出结果
    if status == pywraplp.Solver.OPTIMAL:
        selected_items = []
        total_weight = 0
        total_value = 0
        for i in range(len(items)):
            if x[i].solution_value() > 0.5:
                selected_items.append(items[i])
                total_weight += weights[i]
                total_value += values[i]

        print("最优解：")
        print(f"选择的设备: {selected_items}")
        print(f"总重量: {total_weight}")
        print(f"总价值: {total_value}")

        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))
    else:
        print("__STEPORLM_RESULT__=" + json.dumps(_steporlm_emit_result(locals(), globals()), ensure_ascii=False))

solve_knapsack()
